/// A fifty-page syndicated credit agreement. The cover says only "dated as
/// of the Closing Date"; the Closing Date itself is defined in Article I,
/// pages into the definitions. Sixteen lenders, two arrangers, a former
/// agent, and a dozen subsidiaries are named; the parties to file it under
/// are the borrower and the administrative agent.
import { Flow } from '../lib/layout.mjs';
import { Rng } from '../lib/rng.mjs';
import { gold } from '../lib/gold.mjs';
import { addMonths, decimal, endOfMonth, longDate, money } from '../lib/format.mjs';
import { digitalPdf, result } from './common.mjs';
import { pageContaining } from './contracts.mjs';

const BORROWER = 'Marrowfield Packaging Holdings, Inc.';
const AGENT = 'Halden Bay National Bank, N.A.';
const LENDERS = [
  AGENT, 'Kestrel Ridge Commercial Bank', 'Copper Flats Savings Bank', 'Tamsin Valley Bank & Trust', 'Bellmoor State Bank',
  'Oriel Junction National Bank', 'Gilchrist Harbor Savings Bank', 'Pemberly Falls Trust Company', 'Westharrow Community Bank',
  'Dunmore Lake National Bank', 'Silverlode Capital Bank', 'Fallow Creek Bank', 'Quarry Bend Federal Bank', 'Ashworth Commercial Bank',
  'Briarport Business Bank', 'Larchmont Heights Bank',
];
const ARRANGERS = ['Halden Bay Capital Markets LLC', 'Kestrel Ridge Securities LLC'];
const EXISTING_AGENT = 'Wrenfield Commercial Bank';
const SUBSIDIARIES = [
  ['Marrowfield Packaging LLC', 'Delaware', '100%', 'Guarantor'],
  ['Marrowfield Flexibles LLC', 'Ohio', '100%', 'Guarantor'],
  ['Ostrander Label Company', 'Wisconsin', '100%', 'Guarantor'],
  ['Cinder Street Corrugated Inc.', 'Pennsylvania', '100%', 'Guarantor'],
  ['Marrowfield Molded Fiber LLC', 'Michigan', '100%', 'Guarantor'],
  ['Basalt Drive Inks LLC', 'Utah', '80%', 'Non-guarantor (joint venture)'],
  ['Marrowfield Packaging Canada ULC', 'British Columbia', '100%', 'Foreign Subsidiary'],
  ['Marrowfield Empaques de Mexico, S. de R.L. de C.V.', 'Mexico', '99.9%', 'Foreign Subsidiary'],
  ['Pennant Street Realty LLC', 'Delaware', '100%', 'Guarantor'],
  ['MPH Insurance Services Inc.', 'Vermont', '100%', 'Captive insurer; Excluded Subsidiary'],
];

export function creditAgreement() {
  const id = 'credit-agreement-50p';
  const rng = Rng.from(id);
  const closing = '2026-06-12';
  const maturity = '2031-06-12';
  const existingDate = '2021-09-30';
  const firstTest = '2026-09-30';
  const revolving = 10000000000;
  const termA = 25000000000;
  const flow = new Flow({
    face: 'serif', fontSize: 12, leading: 1.5, margins: { top: 72, bottom: 72, left: 90, right: 90 }, keep: [BORROWER, AGENT, ...LENDERS],
    footer: (page, { number }) => {
      if (number > 1) page.textCenter(306, 750, String(number), { face: 'serif', size: 10 });
    },
  });
  // Cover.
  const cover = flow.page;
  let y = 150;
  for (const [text, options] of [
    ['CREDIT AGREEMENT', { face: 'sans-bold', size: 18 }],
    ['', {}],
    ['Dated as of the Closing Date (as defined herein)', { face: 'serif', size: 12 }],
    ['', {}],
    ['among', { face: 'serif', size: 12 }],
    [BORROWER.toUpperCase(), { face: 'sans-bold', size: 12 }],
    ['as the Borrower,', { face: 'serif', size: 12 }],
    ['', {}],
    ['THE LENDERS PARTY HERETO,', { face: 'sans-bold', size: 12 }],
    ['', {}],
    ['and', { face: 'serif', size: 12 }],
    [AGENT.toUpperCase(), { face: 'sans-bold', size: 12 }],
    ['as Administrative Agent, Swing Line Lender, and L/C Issuer', { face: 'serif', size: 12 }],
    ['', {}],
    [`${money(revolving + termA, { cents: false })} SENIOR SECURED CREDIT FACILITIES`, { face: 'sans-bold', size: 12 }],
    ['', {}],
    [`${ARRANGERS[0].toUpperCase()} and`, { face: 'serif', size: 11 }],
    [ARRANGERS[1].toUpperCase(), { face: 'serif', size: 11 }],
    ['as Joint Lead Arrangers and Joint Bookrunners', { face: 'serif', size: 11 }],
  ]) {
    if (text) cover.textCenter(306, y, text, options);
    y += 22;
  }
  flow.pageBreak();

  const definitions = creditDefinitions({ closing, maturity, existingDate, revolving, termA, rng: rng.fork('definitions') });
  const articles = creditArticles({ closing, maturity, firstTest, revolving, termA, rng: rng.fork('articles') });

  // Table of contents.
  flow.heading('TABLE OF CONTENTS', { level: 2, align: 'center' });
  const roman = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X'];
  flow.paragraph('ARTICLE I - DEFINITIONS AND ACCOUNTING TERMS', { face: 'sans-bold', size: 10, after: 1 });
  flow.paragraph('1.01 Defined Terms; 1.02 Other Interpretive Provisions; 1.03 Accounting Terms; 1.04 Rounding; 1.05 Times of Day; 1.06 Letter of Credit Amounts; 1.07 Rates', { size: 10, indent: 18, after: 6 });
  articles.forEach(([title, sections], index) => {
    flow.paragraph(`ARTICLE ${roman[index + 1]} - ${title.toUpperCase()}`, { face: 'sans-bold', size: 10, after: 1 });
    flow.paragraph(sections.map(([heading], sectionIndex) => `${index + 2}.${String(sectionIndex + 1).padStart(2, '0')} ${heading}`).join('; '), { size: 10, indent: 18, after: 6 });
  });
  flow.paragraph('SCHEDULES: 2.01 Commitments and Applicable Percentages; 5.13 Subsidiaries and Other Equity Investments; 7.01 Existing Liens; 7.02 Existing Indebtedness; 10.02 Administrative Agent\'s Office and Certain Addresses for Notices', { size: 10, after: 4 });
  flow.paragraph('EXHIBITS: A Form of Committed Loan Notice; B Form of Compliance Certificate; C Form of Assignment and Assumption; D Form of Note; E Form of Guaranty', { size: 10 });
  flow.pageBreak();

  flow.paragraph(`This CREDIT AGREEMENT is entered into as of the Closing Date among ${BORROWER}, a Delaware corporation (the "Borrower"), each lender from time to time party hereto (collectively, the "Lenders" and individually, a "Lender"), and ${AGENT}, as Administrative Agent, Swing Line Lender, and L/C Issuer.`);
  flow.paragraph('PRELIMINARY STATEMENTS:', { face: 'sans-bold', size: 11 });
  flow.paragraph(`The Borrower has requested that the Lenders provide a term loan facility and a revolving credit facility, the proceeds of which will be used on the Closing Date to refinance all indebtedness outstanding under the Existing Credit Agreement, to pay fees and expenses incurred in connection with this Agreement, and thereafter for working capital, capital expenditures, Permitted Acquisitions, and other general corporate purposes. The Lenders are willing to do so on the terms and subject to the conditions set forth herein. In consideration of the mutual covenants and agreements herein contained, the parties hereto covenant and agree as follows:`);
  flow.heading('ARTICLE I', { level: 3, align: 'center', after: 0 });
  flow.paragraph('DEFINITIONS AND ACCOUNTING TERMS', { face: 'sans-bold', size: 11, align: 'center' });
  flow.paragraph([{ text: '1.01 Defined Terms. ', face: 'sans-bold' }, { text: 'As used in this Agreement, the following terms have the meanings set forth below:' }]);
  for (const [term, meaning, table] of definitions) {
    flow.paragraph([{ text: `"${term}" `, face: 'sans-bold' }, { text: meaning }], { firstIndent: 36 });
    if (table) flow.table(table.columns, table.rows, { size: 10 });
  }
  for (const [heading, body] of [
    ['1.02 Other Interpretive Provisions', 'The definitions of terms apply equally to the singular and plural forms of the terms defined. The words "include," "includes," and "including" are deemed to be followed by "without limitation." References to any agreement are to that agreement as amended, restated, supplemented, or otherwise modified from time to time to the extent not prohibited by this Agreement. Section headings are for convenience only.'],
    ['1.03 Accounting Terms', 'All accounting terms not specifically defined have the meanings given them under GAAP applied on a basis consistent with the Audited Financial Statements. If any change in GAAP would affect the computation of any financial ratio, the Borrower and the Required Lenders will negotiate in good faith to amend the ratio to preserve its original intent, and until so amended the ratio will be computed as if the change had not occurred. Leases are treated in accordance with GAAP as in effect on December 31, 2018 for purposes of the definition of Indebtedness.'],
    ['1.04 Rounding', 'Any financial ratio required to be maintained by the Borrower is calculated by dividing the appropriate component by the other component, carrying the result to one place more than the number of places by which the ratio is expressed, and rounding the result up or down to the nearest number, with a rounding-up if there is no nearest number.'],
    ['1.05 Times of Day', 'Unless otherwise specified, all references to times of day are references to Pacific time (daylight or standard, as applicable).'],
    ['1.06 Letter of Credit Amounts', 'The amount of a Letter of Credit at any time is its stated amount then in effect; if a Letter of Credit provides for one or more automatic increases in its stated amount, its amount is the maximum stated amount after giving effect to all such increases, whether or not that maximum is in effect at the time.'],
    ['1.07 Rates', 'The Administrative Agent does not warrant, and is not responsible for, the administration, submission, or calculation of any reference rate, or the effect of any of the foregoing, or of any Conforming Changes, on the rates payable under this Agreement.'],
  ]) flow.paragraph([{ text: `${heading}. `, face: 'sans-bold' }, { text: body }]);

  articles.forEach(([title, sections], index) => {
    flow.heading(`ARTICLE ${roman[index + 1]}`, { level: 3, align: 'center', after: 0, before: 14 });
    flow.paragraph(title.toUpperCase(), { face: 'sans-bold', size: 11, align: 'center', keepWithNext: 40 });
    sections.forEach(([heading, body, items, table], sectionIndex) => {
      flow.paragraph([{ text: `${index + 2}.${String(sectionIndex + 1).padStart(2, '0')} ${heading}. `, face: 'sans-bold' }, { text: body }]);
      (items ?? []).forEach((item, itemIndex) => flow.paragraph(`(${String.fromCharCode(97 + itemIndex)}) ${item}`, { indent: 36 }));
      if (table) flow.table(table.columns, table.rows, { size: 10 });
    });
  });

  // Signature pages: the borrower, then the agent, then every lender.
  flow.pageBreak();
  flow.paragraph('IN WITNESS WHEREOF, the parties hereto have caused this Agreement to be duly executed as of the date first above written.', { after: 14 });
  const signers = people12(rng.fork('signers'));
  const blocks = [[BORROWER.toUpperCase(), 'as the Borrower', signers[0], 'Chief Financial Officer'], [AGENT.toUpperCase(), 'as Administrative Agent, Swing Line Lender, L/C Issuer, and a Lender', signers[1], 'Managing Director'],
    ...LENDERS.slice(1).map((lender, index) => [lender.toUpperCase(), 'as a Lender', signers[(index + 2) % signers.length], rng.pick(['Senior Vice President', 'Vice President', 'Director', 'Authorized Signatory'])])];
  for (let index = 0; index < blocks.length; index += 2) {
    const pair = blocks.slice(index, index + 2);
    flow.ensure(110);
    const top = flow.y;
    pair.forEach(([entity, role, person, title], column) => {
      const x = flow.left + column * 220;
      const lines = [[entity, 'sans-bold', 9], [role, 'serif', 10], ['', 'serif', 10], [`By: /s/ ${person}`, 'serif', 10], [`Name: ${person}`, 'serif', 10], [`Title: ${title}`, 'serif', 10]];
      lines.forEach(([text, face, size], line) => {
        if (text) flow.page.text(x, top + 12 + line * 15, text, { face, size });
      });
    });
    flow.y = top + 110;
  }
  flow.paragraph('[Signature Pages to Credit Agreement]', { align: 'center', size: 10, grey: 0.3 });

  // Schedules.
  flow.pageBreak();
  flow.heading('Schedule 2.01 - Commitments and Applicable Percentages', { level: 3 });
  const shares = COMMITMENT_SHARES;
  let totalRevolving = 0;
  let totalTerm = 0;
  const commitmentRows = LENDERS.map((lender, index) => {
    const revolvingShare = Math.round((revolving * shares[index]) / 10000);
    const termShare = Math.round((termA * shares[index]) / 10000);
    totalRevolving += revolvingShare;
    totalTerm += termShare;
    return [lender, money(revolvingShare), money(termShare), `${decimal(shares[index], 2)}%`];
  });
  commitmentRows.push([{ text: 'Total', face: 'sans-bold' }, money(totalRevolving), money(totalTerm), '100.00%']);
  flow.table([{ header: 'Lender', width: 0.4 }, { header: 'Revolving Credit Commitment', width: 0.21, align: 'right' }, { header: 'Term A Commitment', width: 0.21, align: 'right' }, { header: 'Applicable Percentage', width: 0.18, align: 'right' }], commitmentRows, { size: 9 });
  flow.heading('Schedule 5.13 - Subsidiaries and Other Equity Investments', { level: 3 });
  flow.table([{ header: 'Subsidiary', width: 0.42 }, { header: 'Jurisdiction', width: 0.2 }, { header: 'Ownership', width: 0.13 }, { header: 'Status', width: 0.25 }], SUBSIDIARIES, { size: 9 });
  flow.heading('Schedule 7.01 - Existing Liens', { level: 3 });
  flow.table([{ header: 'Debtor', width: 0.3 }, { header: 'Secured party', width: 0.3 }, { header: 'Collateral', width: 0.25 }, { header: 'Filing', width: 0.15 }], [
    ['Marrowfield Flexibles LLC', 'Ollerton Equipment Leasing', 'Eight-color flexographic press', 'OH 2024-118204'],
    ['Cinder Street Corrugated Inc.', 'Linden Cross Trust Company', 'Corrugator line 2 (purchase money)', 'PA 2023-60411'],
    ['Pennant Street Realty LLC', 'Fallow Creek Bank', 'Mortgage on 400 Pennant Street (Briarport warehouse)', 'Recorded Bk 2207 Pg 114'],
    ['Marrowfield Packaging Canada ULC', 'Copper Flats Savings Bank', 'Equipment at Surrey, B.C. plant', 'PPSA 552183F'],
  ], { size: 9 });
  flow.heading('Schedule 7.02 - Existing Indebtedness', { level: 3 });
  flow.table([{ header: 'Obligor', width: 0.32 }, { header: 'Description', width: 0.44 }, { header: 'Outstanding', width: 0.24, align: 'right' }], [
    ['Cinder Street Corrugated Inc.', 'Purchase money note, matures 2029', money(612000000)],
    ['Pennant Street Realty LLC', 'Mortgage loan, matures 2033', money(1475000000)],
    ['Marrowfield Packaging Canada ULC', 'Equipment financing (CAD 4.1 million)', money(298000000)],
    ['Marrowfield Empaques de Mexico', 'Working capital line (undrawn)', money(0)],
    ['Basalt Drive Inks LLC', 'Note payable to joint venture partner', money(84000000)],
  ], { size: 9 });
  flow.heading('Schedule 10.02 - Administrative Agent\'s Office; Addresses for Notices', { level: 3 });
  flow.paragraph(`Borrower: ${BORROWER}, 2210 Marrowfield Road, Marrow Springs, CO 80512, Attention: Treasurer; email treasury@marrowfield-packaging.example. Administrative Agent: ${AGENT}, Agency Services, 50 Calder Way, 12th Floor, Halden Bay, WA 98264, Attention: Loan Agency; email agency@haldenbaynational.example.`, { size: 11 });

  flow.pageBreak();
  flow.heading('Schedule 5.17 - Intellectual Property', { level: 3 });
  flow.table([{ header: 'Owner', width: 0.32 }, { header: 'Mark or patent', width: 0.3 }, { header: 'Registration / patent no.', width: 0.22 }, { header: 'Jurisdiction', width: 0.16 }], [
    ['Marrowfield Packaging LLC', 'MARROWFIELD (word)', '4,872,019', 'United States'],
    ['Marrowfield Packaging LLC', 'MARROWFIELD (and design)', '4,872,020', 'United States'],
    ['Marrowfield Flexibles LLC', 'FRESHLOCK reclosable pouch', 'Patent 11,402,775', 'United States'],
    ['Marrowfield Flexibles LLC', 'Peel-reseal laminate structure', 'Patent 11,918,306', 'United States'],
    ['Ostrander Label Company', 'OSTRANDER (word)', '3,991,442', 'United States'],
    ['Marrowfield Molded Fiber LLC', 'Molded fiber clamshell with living hinge', 'Patent 12,005,881', 'United States'],
    ['Marrowfield Packaging Canada ULC', 'MARROWFIELD', 'TMA1,144,207', 'Canada'],
  ], { size: 9 });
  flow.heading('Schedule 5.09 - Environmental Matters', { level: 3 });
  flow.paragraph('Linden Cross, Pennsylvania plant: trichloroethylene in groundwater from degreasing operations discontinued in 2004; remediation under consent order with the state environmental agency; pump-and-treat system operating since 2019; remaining estimated cost $1,350,000, fully reserved. Marrow Springs, Colorado plant: stormwater permit renewal pending, filed timely. No other matters.', { size: 11 });
  flow.heading('Schedule 6.14 - Post-Closing Obligations', { level: 3 });
  flow.table([{ header: 'Obligation', width: 0.6 }, { header: 'Deadline after the Closing Date', width: 0.4 }], [
    ['Deposit account control agreements (11 accounts at 4 banks)', '30 days'],
    ['Insurance endorsements (property and general liability)', '60 days'],
    ['Mortgages, title policies, surveys, and flood determinations for the two Material Real Properties', '90 days'],
    ['Landlord access agreements for the leased Briarport and Silverlode warehouses', '90 days (commercially reasonable efforts)'],
    ['Stock certificates and stock powers for Ostrander Label Company', '15 days'],
  ], { size: 9 });
  flow.pageBreak();
  flow.heading('EXHIBIT A - FORM OF COMMITTED LOAN NOTICE', { level: 3, align: 'center' });
  flow.paragraph('Date: ___________, _____', { size: 11 });
  flow.paragraph(`To: ${AGENT}, as Administrative Agent`, { size: 11 });
  flow.paragraph('Ladies and Gentlemen:', { size: 11 });
  flow.paragraph(`Reference is made to the Credit Agreement dated as of the Closing Date (as amended, restated, extended, supplemented, or otherwise modified in writing from time to time, the "Agreement") among ${BORROWER} (the "Borrower"), the Lenders from time to time party thereto, and ${AGENT}, as Administrative Agent, Swing Line Lender, and L/C Issuer. The undersigned hereby requests (select one): [ ] a Borrowing of Term A Loans; [ ] a Borrowing of Revolving Credit Loans; [ ] a conversion or continuation of Loans.`, { size: 11 });
  flow.table([{ header: 'Item', width: 0.5 }, { header: 'Requested', width: 0.5 }], [['On (a Business Day)', ''], ['In the amount of', '$'], ['Comprised of (Type of Loan requested)', 'Base Rate / Term SOFR'], ['For Term SOFR Loans: with an Interest Period of', '1 / 3 / 6 months']], { size: 10 });
  flow.paragraph('The Borrower hereby represents and warrants that the conditions specified in Section 4.02 have been satisfied on and as of the date of the requested Borrowing, and that after giving effect to the Borrowing the Total Revolving Credit Outstandings will not exceed the Revolving Credit Facility.', { size: 11 });
  flow.paragraph(`${BORROWER.toUpperCase()}   By: ________________________   Name:   Title:`, { size: 11 });
  // Exhibit B: a filled-in compliance certificate.
  flow.pageBreak();
  flow.heading('EXHIBIT B - FORM OF COMPLIANCE CERTIFICATE', { level: 3, align: 'center' });
  flow.paragraph('Financial Statement Date: ____________, 20__', { size: 11 });
  flow.paragraph(`The undersigned Responsible Officer hereby certifies as of the date hereof that he/she is the Chief Financial Officer of the Borrower, and that, as such, he/she is authorized to execute and deliver this Certificate to the Administrative Agent on behalf of the Borrower, and that: (1) attached hereto are the financial statements required by Section 6.01 for the fiscal period ended as of the above date; (2) a review of the activities of the Borrower during that period has been made with a view to determining whether the Borrower has performed and observed all its obligations under the Loan Documents, and no Default has occurred and is continuing; and (3) the financial covenant analyses set forth on Schedule 1 hereto are true and accurate on and as of the date of this Certificate.`, { size: 11 });
  flow.table([{ header: 'Schedule 1 - Covenant computation (illustrative, pro forma for the Closing Date)', width: 0.7 }, { header: 'Amount', width: 0.3, align: 'right' }], [
    ['Consolidated Net Income for the four fiscal quarters', money(4718000000)],
    ['plus Consolidated Interest Charges', money(1694000000)],
    ['plus income tax expense', money(1512000000)],
    ['plus depreciation and amortization', money(3305000000)],
    ['plus non-cash charges and permitted add-backs (capped)', money(711000000)],
    [{ text: 'Consolidated EBITDA', face: 'sans-bold' }, { text: money(11940000000), face: 'sans-bold' }],
    ['Consolidated Funded Indebtedness', money(39470000000)],
    ['Consolidated Total Leverage Ratio (maximum 3.75 to 1.00)', '3.31 to 1.00'],
    ['Consolidated Fixed Charge Coverage Ratio (minimum 1.25 to 1.00)', '1.86 to 1.00'],
  ], { size: 9.5 });

  flow.pageBreak();
  flow.heading('EXHIBIT C - FORM OF ASSIGNMENT AND ASSUMPTION', { level: 3, align: 'center' });
  flow.paragraph('This Assignment and Assumption is dated as of the Effective Date set forth below and is entered into by and between the Assignor identified below and the Assignee identified below. Capitalized terms used but not defined herein have the meanings given to them in the Credit Agreement identified below, receipt of a copy of which is hereby acknowledged by the Assignee. The Standard Terms and Conditions set forth in Annex 1 attached hereto are hereby agreed to and incorporated herein by reference.', { size: 11 });
  flow.paragraph('For an agreed consideration, the Assignor hereby irrevocably sells and assigns to the Assignee, and the Assignee hereby irrevocably purchases and assumes from the Assignor, subject to and in accordance with the Standard Terms and Conditions and the Credit Agreement, as of the Effective Date inserted by the Administrative Agent: (i) all of the Assignor\'s rights and obligations in its capacity as a Lender under the Credit Agreement and any other Loan Documents to the extent related to the amount and percentage interest identified below of all of its outstanding rights and obligations under the respective facilities identified below; and (ii) to the extent permitted to be assigned under applicable law, all claims, suits, causes of action, and any other right of the Assignor against any Person arising under or in connection with the Credit Agreement.', { size: 11 });
  flow.table([{ header: 'Facility assigned', width: 0.34 }, { header: 'Aggregate amount for all Lenders', width: 0.24 }, { header: 'Amount assigned', width: 0.2 }, { header: 'Percentage assigned', width: 0.22 }], [['Revolving Credit Commitment', money(revolving), '$', '%'], ['Term A Loan', money(termA), '$', '%']], { size: 10 });
  flow.paragraph('Effective Date: _____________, 20__ [TO BE INSERTED BY ADMINISTRATIVE AGENT AND WHICH SHALL BE THE EFFECTIVE DATE OF RECORDATION OF TRANSFER IN THE REGISTER THEREFOR.]', { size: 10.5 });
  flow.paragraph('ASSIGNOR: ____________________   ASSIGNEE: ____________________   Consented to and accepted: ' + AGENT + ', as Administrative Agent', { size: 10.5 });
  flow.heading('ANNEX 1 TO ASSIGNMENT AND ASSUMPTION - STANDARD TERMS AND CONDITIONS', { level: 3 });
  flow.paragraph('1.1 Assignor. The Assignor represents and warrants that it is the legal and beneficial owner of the Assigned Interest, the Assigned Interest is free and clear of any lien, encumbrance, or other adverse claim, and it has full power and authority to execute and deliver this Assignment and Assumption; and assumes no responsibility for any statements, warranties, or representations made in or in connection with the Credit Agreement, the financial condition of the Borrower, or the performance by any Loan Party of its obligations under any Loan Document.', { size: 11 });
  flow.paragraph('1.2 Assignee. The Assignee represents and warrants that it has full power and authority to execute and deliver this Assignment and Assumption and to consummate the transactions contemplated hereby; it meets all the requirements to be an assignee under the Credit Agreement; from and after the Effective Date it shall be bound by the provisions of the Credit Agreement as a Lender and have the obligations of a Lender; it is sophisticated with respect to decisions to acquire assets of the type represented by the Assigned Interest; and it has independently and without reliance upon the Administrative Agent or any other Lender made its own credit analysis and decision to enter into this Assignment and Assumption.', { size: 11 });
  flow.paragraph('2. Payments. From and after the Effective Date, the Administrative Agent shall make all payments in respect of the Assigned Interest, including payments of principal, interest, fees, and other amounts, to the Assignor for amounts which have accrued to but excluding the Effective Date and to the Assignee for amounts which have accrued from and after the Effective Date.', { size: 11 });
  flow.paragraph('3. General Provisions. This Assignment and Assumption shall be binding upon, and inure to the benefit of, the parties hereto and their respective successors and assigns, may be executed in any number of counterparts, and shall be governed by, and construed in accordance with, the law of the State of New York.', { size: 11 });
  flow.pageBreak();
  flow.heading('EXHIBIT D - FORM OF NOTE', { level: 3, align: 'center' });
  flow.paragraph(`FOR VALUE RECEIVED, the undersigned (the "Borrower") hereby promises to pay to ____________________ or registered assigns (the "Lender"), in accordance with the provisions of the Credit Agreement, the principal amount of each Loan from time to time made by the Lender to the Borrower under that certain Credit Agreement, dated as of the Closing Date (as amended, restated, extended, supplemented, or otherwise modified in writing from time to time, the "Agreement"), among the Borrower, the Lenders from time to time party thereto, and ${AGENT}, as Administrative Agent, Swing Line Lender, and L/C Issuer.`, { size: 11 });
  flow.paragraph('The Borrower promises to pay interest on the unpaid principal amount of each Loan from the date of that Loan until it is paid in full, at the rates and at the times provided in the Agreement. All payments of principal and interest shall be made directly to the Administrative Agent for the account of the Lender in Dollars in immediately available funds at the Administrative Agent\'s Office. If any amount is not paid in full when due hereunder, that unpaid amount shall bear interest, to be paid upon demand, from the due date thereof until the date of actual payment (and before as well as after judgment) computed at the per annum rate set forth in the Agreement.', { size: 11 });
  flow.paragraph('This Note is one of the Notes referred to in the Agreement, is entitled to the benefits thereof, and may be prepaid in whole or in part subject to the terms and conditions provided therein. This Note is also entitled to the benefits of the Guaranty and is secured by the Collateral. Upon the occurrence and continuation of one or more of the Events of Default specified in the Agreement, all amounts then remaining unpaid on this Note shall become, or may be declared to be, immediately due and payable all as provided in the Agreement. THIS NOTE SHALL BE GOVERNED BY AND CONSTRUED IN ACCORDANCE WITH THE LAW OF THE STATE OF NEW YORK.', { size: 11 });
  flow.paragraph(`${BORROWER.toUpperCase()}   By: ________________________   Name:   Title:`, { size: 11 });
  flow.pageBreak();
  flow.heading('EXHIBIT E - FORM OF GUARANTY (PRINCIPAL TERMS)', { level: 3, align: 'center' });
  [
    ['Guaranty', 'Each Guarantor, jointly and severally with each other Guarantor, irrevocably and unconditionally guarantees to the Administrative Agent, for the benefit of the Secured Parties, the prompt payment and performance when due, whether at stated maturity, by required prepayment, upon acceleration, or otherwise, of all of the Obligations. This is a guaranty of payment and not merely of collection.'],
    ['Limitation', 'The obligations of each Guarantor are limited to the maximum amount that would not render its obligations subject to avoidance under Section 548 of the Bankruptcy Code or any comparable provision of state law, after giving effect to all other liabilities of that Guarantor and to any rights of contribution from other Guarantors.'],
    ['Obligations Unconditional', 'The obligations of each Guarantor are absolute and unconditional, irrespective of the value, genuineness, validity, regularity, or enforceability of the Loan Documents, any amendment or waiver thereof, any release of Collateral or of any other Guarantor, or any other circumstance that might otherwise constitute a legal or equitable discharge or defense of a surety or guarantor.'],
    ['Waivers', 'Each Guarantor waives diligence, presentment, demand of payment, protest, notice of acceptance of this Guaranty, and all other notices, any requirement that the Administrative Agent exhaust any right or take any action against the Borrower or any other Person or any Collateral, and any right to require the marshaling of assets.'],
    ['Subrogation; Subordination', 'No Guarantor shall exercise any right of subrogation, contribution, or indemnity against the Borrower or any other Loan Party until the Obligations have been paid in full in cash and the Commitments have terminated. Any Indebtedness of any Loan Party owing to a Guarantor is subordinated to the Obligations, and any payment received in respect of it after an Event of Default shall be held in trust for the Administrative Agent.'],
    ['Keepwell', 'Each Qualified ECP Guarantor jointly and severally undertakes to provide such funds or other support as may be needed from time to time by each other Loan Party to honor all of its obligations under this Guaranty in respect of Swap Obligations, up to the maximum amount for which that Qualified ECP Guarantor can be liable without rendering its obligations voidable.'],
    ['Release', 'A Guarantor shall be automatically released from this Guaranty upon the consummation of any transaction permitted by the Credit Agreement as a result of which it ceases to be a Subsidiary, and all Guarantors shall be released when the Obligations have been paid in full in cash, the Commitments have terminated, and all Letters of Credit have expired or been Cash Collateralized.'],
  ].forEach(([title, body], index) => flow.paragraph([{ text: `${index + 1}. ${title}. `, face: 'sans-bold' }, { text: body }], { size: 10.5 }));
  flow.paragraph(`Guarantors as of the Closing Date: ${SUBSIDIARIES.filter(([, , , status]) => status === 'Guarantor').map(([name]) => name).join('; ')}.`, { size: 10.5 });
  const pages = flow.finish();
  const { bytes, text } = digitalPdf(pages);
  const closingPage = pageContaining(text, `"Closing Date" means ${longDate(closing)}`);
  if (closingPage < 9 || closingPage > 12) throw new Error(`${id}: the Closing Date definition must fall on pages 9-12, not ${closingPage}`);
  if (pages.length !== 50) throw new Error(`${id}: expected 50 pages, laid out ${pages.length}`);
  return result({
    id,
    extension: 'pdf',
    files: [{ name: `${id}.pdf`, bytes }],
    text,
    title: 'Fifty-page syndicated credit agreement whose date is defined in Article I',
    kind: 'contract',
    textLayer: 'native',
    pages: pages.length,
    categories: ['pages_50', 'contract', 'middle_fact', 'referenced_agreement', 'irrelevant_names', 'competing_dates', 'table', 'information_dense'],
    notes: `The cover and preamble say only "dated as of the Closing Date"; the date itself is the definition "Closing Date" means ${longDate(closing)}, on page ${closingPage} inside Article I. The Existing Credit Agreement (${longDate(existingDate)}) and the Maturity Date (${longDate(maturity)}) are defined nearby, and the first covenant test date (${longDate(firstTest)}) recurs. Sixteen lenders sign and fill Schedule 2.01, two arrangers are on the cover, and the former agent and ten subsidiaries are named; the agreement is filed between the Borrower and the Administrative Agent, the two parties named in the preamble.`,
    gold: gold({
      type: 'Credit Agreement',
      date: closing,
      role: 'effective',
      forbiddenDates: [[existingDate, 'date of the Existing Credit Agreement being refinanced'], [maturity, 'Maturity Date'], [firstTest, 'first financial covenant test date and amortization date']],
      parties: [BORROWER, AGENT],
      relation: 'between',
      acceptablePartySets: [{ parties: [BORROWER], relation: 'for' }, { parties: [BORROWER], relation: 'with' }],
      roles: [[BORROWER, 'borrower'], [AGENT, 'lender']],
      forbiddenParties: [[LENDERS[1], 'lender'], [LENDERS[2], 'lender'], [ARRANGERS[0], 'joint lead arranger'], [EXISTING_AGENT, 'agent under the Existing Credit Agreement'], [SUBSIDIARIES[0][0], 'subsidiary guarantor']],
      facts: [[money(revolving + termA, { cents: false }), '$350,000,000', '350 million', '$350 million'], ['revolving', 'term loan', 'Term A'], [longDate(maturity), '2031', 'five-year']],
      subjectTerms: ['credit agreement', 'senior secured', 'revolving credit', 'term loan'],
      readiness: 'ready',
      dateText: [longDate(closing)],
    }),
  });
}

/// Twelve signatory names for the signature pages.
function people12(rng) {
  const first = ['Adaeze', 'Bram', 'Celeste', 'Dashiell', 'Elodie', 'Florian', 'Greer', 'Hollis', 'Ilse', 'Jasper', 'Keziah', 'Lionel'];
  const last = ['Achterberg', 'Boateng', 'Coldwell', 'Dunmore', 'Eckhardt', 'Fennimore', 'Galbraith', 'Halloran', 'Iwasaki', 'Jaramillo', 'Kavanagh', 'Lockridge'];
  return rng.shuffle(first).map((name, index) => `${name} ${rng.shuffle(last)[index]}`);
}

/// Sixteen lender shares in hundredths of a percent, summing to 10000:
/// the agent and the second arranger hold the largest pieces, as they do in
/// a real syndicate.
const COMMITMENT_SHARES = [1450, 1150, 900, 800, 750, 700, 650, 600, 550, 500, 450, 400, 350, 300, 275, 225];

function creditDefinitions({ closing, maturity, existingDate, revolving, termA, rng }) {
  const pricing = {
    columns: [{ header: 'Pricing Level', width: 0.16 }, { header: 'Consolidated Total Leverage Ratio', width: 0.36 }, { header: 'Term SOFR Loans and Letter of Credit Fee', width: 0.2, align: 'right' }, { header: 'Base Rate Loans', width: 0.14, align: 'right' }, { header: 'Commitment Fee', width: 0.14, align: 'right' }],
    rows: [['1', '< 1.50:1.00', '1.375%', '0.375%', '0.175%'], ['2', '>= 1.50:1.00 but < 2.25:1.00', '1.625%', '0.625%', '0.200%'], ['3', '>= 2.25:1.00 but < 3.00:1.00', '1.875%', '0.875%', '0.250%'], ['4', '>= 3.00:1.00 but < 3.50:1.00', '2.125%', '1.125%', '0.300%'], ['5', '>= 3.50:1.00', '2.375%', '1.375%', '0.350%']],
  };
  const threshold = money(rng.pick([2500000000, 3000000000]), { cents: false });
  return [
    ['Acquisition', 'means the acquisition, whether by purchase, merger, or otherwise, of all or substantially all of the assets of, or a business line, product line, or division of, any Person, or of more than fifty percent of the Equity Interests of any Person.'],
    ['Additional Lender', 'has the meaning specified in Section 2.16(c), being any bank, financial institution, or other institutional lender that agrees to provide all or part of an Incremental Facility and is reasonably acceptable to the Administrative Agent.'],
    ['Administrative Agent', `means ${AGENT}, in its capacity as administrative agent under any of the Loan Documents, or any successor administrative agent appointed under Article IX.`],
    ['Agent Parties', 'means the Administrative Agent and its Related Parties, in their capacities as such, including in connection with the Platform and the distribution of Borrower Materials.'],
    ['Anti-Corruption Laws', 'means the United States Foreign Corrupt Practices Act of 1977, the UK Bribery Act 2010, and all other laws, rules, and regulations of any jurisdiction applicable to the Borrower or its Subsidiaries from time to time concerning or relating to bribery or corruption.'],
    ['Administrative Agent\'s Office', 'means the Administrative Agent\'s address and, as appropriate, account as set forth on Schedule 10.02, or such other address or account as the Administrative Agent may from time to time notify to the Borrower and the Lenders.'],
    ['Affiliate', 'means, with respect to a specified Person, another Person that directly, or indirectly through one or more intermediaries, Controls or is Controlled by or is under common Control with the Person specified; provided that no Lender shall be an Affiliate of the Borrower solely by reason of holding Loans.'],
    ['Aggregate Commitments', `means the Commitments of all the Lenders, which on the Closing Date are ${money(revolving + termA, { cents: false })}, consisting of Revolving Credit Commitments of ${money(revolving, { cents: false })} and Term A Commitments of ${money(termA, { cents: false })}.`],
    ['Applicable Revolving Credit Percentage', 'means, with respect to any Revolving Credit Lender at any time, the percentage of the Revolving Credit Facility represented by that Lender\'s Revolving Credit Commitment at that time, subject to adjustment as provided in Section 2.15; if the Revolving Credit Commitments have terminated or expired, the Applicable Revolving Credit Percentage of each Lender is determined based on its most recent Applicable Revolving Credit Percentage, giving effect to any subsequent assignments.'],
    ['Applicable Percentage', 'means, with respect to any Lender at any time, (a) in respect of the Revolving Credit Facility, the percentage of the Revolving Credit Facility represented by that Lender\'s Revolving Credit Commitment, and (b) in respect of the Term A Facility, the percentage of the outstanding principal amount of the Term A Loans held by that Lender, in each case as set forth opposite its name on Schedule 2.01 or in the Assignment and Assumption by which it becomes a party.'],
    ['Applicable Rate', 'means, from time to time, the following percentages per annum, based upon the Consolidated Total Leverage Ratio as set forth in the most recent Compliance Certificate received by the Administrative Agent under Section 6.02(a); provided that from the Closing Date until the first Business Day after delivery of the Compliance Certificate for the fiscal quarter ending September 30, 2026, Pricing Level 3 applies:', pricing],
    ['Approved Fund', 'means any Fund that is administered or managed by (a) a Lender, (b) an Affiliate of a Lender, or (c) an entity or an Affiliate of an entity that administers or manages a Lender.'],
    ['Approved Bank', 'means a commercial bank organized under the laws of the United States or any State thereof having combined capital and surplus of not less than $500,000,000 and a long-term unsecured debt rating of at least A or A2.'],
    ['Asset Sale', 'means any Disposition of property by the Borrower or any Subsidiary (including any sale and leaseback transaction and any issuance of Equity Interests by a Subsidiary), other than Dispositions permitted by clauses (a) through (h) of Section 7.05.'],
    ['Assignment and Assumption', 'means an assignment and assumption entered into by a Lender and an Eligible Assignee, with the consent of any party whose consent is required by Section 10.06(b), and accepted by the Administrative Agent, in substantially the form of Exhibit C.'],
    ['Attributable Indebtedness', 'means, on any date, (a) in respect of any finance lease of any Person, the capitalized amount thereof that would appear on a balance sheet of that Person prepared as of that date in accordance with GAAP, and (b) in respect of any synthetic lease, the capitalized amount of the remaining lease payments that would appear on a balance sheet if the lease were accounted for as a finance lease.'],
    ['Audited Financial Statements', 'means the audited consolidated balance sheet of the Borrower and its Subsidiaries for the fiscal year ended December 31, 2025, and the related consolidated statements of income, shareholders\' equity, and cash flows for that fiscal year, including the notes thereto, audited by Wainwright Lindqvist LLP.'],
    ['Available Amount', 'means, at any time, a cumulative amount equal to (a) the greater of $25,000,000 and 20% of Consolidated EBITDA, plus (b) 50% of Consolidated Net Income for the period from July 1, 2026 to the end of the most recent fiscal quarter for which financial statements have been delivered (or, if negative, minus 100% of the deficit), plus (c) the net cash proceeds of any issuance of Qualified Equity Interests, minus (d) amounts previously applied to Restricted Payments and Investments in reliance on the Available Amount.'],
    ['Availability Period', 'means, in respect of the Revolving Credit Facility, the period from and including the Closing Date to the earliest of the Maturity Date, the date of termination of the Revolving Credit Commitments under Section 2.07, and the date of termination of the commitment of each Revolving Credit Lender to make Revolving Credit Loans and of the obligation of the L/C Issuer to make L/C Credit Extensions under Section 8.02.'],
    ['Bail-In Action', 'means the exercise of any Write-Down and Conversion Powers by the applicable resolution authority in respect of any liability of an Affected Financial Institution.'],
    ['Bail-In Legislation', 'means, with respect to any EEA Member Country implementing Article 55 of Directive 2014/59/EU, the implementing law, regulation, rule, or requirement for that country, and with respect to the United Kingdom, Part I of the United Kingdom Banking Act 2009 and any other law applicable in the United Kingdom relating to the resolution of unsound or failing banks, investment firms, or other financial institutions or their affiliates.'],
    ['Bankruptcy Code', 'means Title 11 of the United States Code, as amended from time to time.'],
    ['Base Rate', 'means for any day a fluctuating rate per annum equal to the highest of (a) the Federal Funds Rate plus one-half of one percent, (b) the rate of interest in effect for that day as publicly announced from time to time by the Administrative Agent as its "prime rate," (c) Term SOFR for a one-month tenor plus one percent, and (d) one percent; any change in the Base Rate due to a change in any of these rates takes effect at the opening of business on the day of the change.'],
    ['Benchmark Replacement', 'means, with respect to any Benchmark Transition Event, the first alternative set forth below that can be determined by the Administrative Agent: (a) Daily Simple SOFR; or (b) the sum of an alternate benchmark rate selected by the Administrative Agent and the Borrower giving due consideration to any selection or recommendation of a replacement rate by the Relevant Governmental Body or any evolving or then-prevailing market convention for determining a rate of interest as a replacement for the then-current Benchmark for syndicated credit facilities denominated in Dollars, plus a related spread adjustment; provided that if the Benchmark Replacement as so determined would be less than zero, it shall be deemed to be zero.'],
    ['Benchmark Transition Event', 'means a public statement or publication of information by or on behalf of the administrator of the then-current Benchmark, the regulatory supervisor for that administrator, or a Governmental Authority with jurisdiction over it, announcing that the administrator has ceased or will cease to provide all available tenors of that Benchmark permanently or indefinitely, or that all available tenors are no longer, or as of a specified future date will no longer be, representative.'],
    ['Beneficial Ownership Certification', 'means a certification regarding beneficial ownership or control as required by the Beneficial Ownership Regulation, in form and substance reasonably satisfactory to the Administrative Agent and each requesting Lender.'],
    ['Borrower Materials', 'has the meaning specified in Section 6.02, being materials and information provided by or on behalf of the Borrower that are posted on the Platform for the Lenders.'],
    ['Borrowing', 'means a Revolving Credit Borrowing, a Swing Line Borrowing, or a Term A Borrowing, as the context may require, in each case consisting of simultaneous Loans of the same Type and, in the case of Term SOFR Loans, having the same Interest Period.'],
    ['Business Day', 'means any day other than a Saturday, Sunday, or other day on which commercial banks are authorized to close under the laws of, or are in fact closed in, the state where the Administrative Agent\'s Office is located.'],
    ['Board of Directors', 'means, with respect to any Person, the board of directors or comparable governing body of that Person, or any committee thereof duly authorized to act on its behalf.'],
    ['Capital Expenditures', 'means, for any period, the aggregate of all expenditures by the Borrower and its Subsidiaries for the acquisition or leasing of fixed or capital assets or additions to equipment that would be required by GAAP to be classified as capital expenditures, excluding expenditures financed with insurance or condemnation proceeds or the proceeds of Asset Sales that are reinvested under Section 2.05(b)(ii).'],
    ['Cash Collateralize', 'means to pledge and deposit with the Administrative Agent, for the benefit of the L/C Issuer or the Swing Line Lender and the Lenders, as collateral for L/C Obligations or obligations of the Lenders to fund participations, cash or deposit account balances in an amount equal to 103% of the Outstanding Amount of the applicable obligations, under documentation satisfactory to the Administrative Agent.'],
    ['Cash Equivalents', 'means (a) securities issued or fully guaranteed by the United States government having maturities of not more than twelve months; (b) certificates of deposit and time deposits with maturities of not more than twelve months issued by any Lender or any commercial bank having capital and surplus of not less than $500,000,000; (c) commercial paper rated at least A-1 or P-1 maturing within 270 days; and (d) money market funds substantially all of whose assets are investments of the kinds described in clauses (a) through (c).'],
    ['Cash Management Bank', 'means any Person that, at the time it enters into a Cash Management Agreement, is a Lender or an Affiliate of a Lender, or any Person that is a party to a Cash Management Agreement with a Loan Party in existence on the Closing Date and is a Lender or an Affiliate of a Lender on the Closing Date, in each case in its capacity as a party to that Cash Management Agreement.'],
    ['CFC', 'means a Person that is a controlled foreign corporation within the meaning of Section 957 of the Code, and "CFC Holdco" means a Domestic Subsidiary substantially all of the assets of which consist of Equity Interests or indebtedness of one or more CFCs.'],
    ['Cash Management Agreement', 'means any agreement to provide treasury or cash management services, including deposit accounts, overdraft, credit or debit card, purchasing card, electronic funds transfer, and automated clearing house services, between any Loan Party and a Cash Management Bank.'],
    ['Change in Law', 'means the occurrence, after the date of this Agreement, of the adoption or taking effect of any law, rule, regulation, or treaty, any change in its administration, interpretation, or application by any Governmental Authority, or the making or issuance of any request or directive by any Governmental Authority, whether or not having the force of law.'],
    ['Change of Control', 'means an event or series of events by which (a) any person or group becomes the beneficial owner, directly or indirectly, of 35% or more of the Equity Interests of the Borrower entitled to vote for members of its board of directors; or (b) during any period of twelve consecutive months, a majority of the members of that board cease to be composed of individuals who were members at the beginning of the period or whose election was approved by a majority of those members; or (c) any "change of control" or similar event occurs under any Indebtedness of the Borrower in excess of the Threshold Amount.'],
    ['Closing Date', `means ${longDate(closing)}, the first date on which all the conditions precedent in Section 4.01 were satisfied or waived in accordance with Section 10.01.`],
    ['Code', 'means the Internal Revenue Code of 1986, as amended.'],
    ['Collateral', 'means all of the property of the Loan Parties in which Liens are purported to be granted under any of the Collateral Documents, which shall include substantially all personal property of the Loan Parties and the Material Real Property, but shall exclude Excluded Property.'],
    ['Collateral Documents', 'means, collectively, the Security Agreement, the Mortgages, each intellectual property security agreement, each control agreement, and each other agreement or instrument by which any Loan Party grants a Lien on its property to the Administrative Agent for the benefit of the Secured Parties.'],
    ['Commitment', 'means a Term A Commitment or a Revolving Credit Commitment, as the context may require.'],
    ['Committed Loan Notice', 'means a notice of a Term A Borrowing, a Revolving Credit Borrowing, a conversion of Loans from one Type to the other, or a continuation of Term SOFR Loans, which shall be substantially in the form of Exhibit A or such other form as may be approved by the Administrative Agent, appropriately completed and signed by a Responsible Officer of the Borrower.'],
    ['Compliance Certificate', 'means a certificate substantially in the form of Exhibit B.'],
    ['Consolidated EBITDA', 'means, for any period, Consolidated Net Income for that period plus, without duplication and to the extent deducted in calculating Consolidated Net Income: (a) Consolidated Interest Charges; (b) the provision for federal, state, local, and foreign income taxes; (c) depreciation and amortization expense; (d) non-cash charges, including non-cash stock compensation and impairment of goodwill; (e) restructuring charges, integration costs, and plant closure costs not exceeding, together with clause (f), 15% of Consolidated EBITDA for the period; (f) projected cost savings from actions taken within the period, reasonably identifiable and expected to be realized within eighteen months; and (g) fees and expenses incurred in connection with this Agreement and any Permitted Acquisition; minus non-cash gains included in Consolidated Net Income.'],
    ['Consolidated Fixed Charge Coverage Ratio', 'means, as of the end of any fiscal quarter, the ratio of (a) Consolidated EBITDA minus unfinanced Capital Expenditures and cash taxes paid, in each case for the four fiscal quarters then ended, to (b) the sum of Consolidated Interest Charges paid in cash, scheduled principal payments of Indebtedness, and Restricted Payments made in cash, in each case for that period.'],
    ['Consolidated Funded Indebtedness', 'means, as of any date, the sum without duplication of all Indebtedness for borrowed money, the outstanding principal amount of purchase money Indebtedness, Attributable Indebtedness, drawn and unreimbursed amounts under letters of credit, and Guarantees of any of the foregoing, of the Borrower and its Subsidiaries on a consolidated basis.'],
    ['Consolidated Interest Charges', 'means, for any period, the sum of all interest, premium payments, debt discount, fees, charges, and related expenses in connection with borrowed money or the deferred purchase price of assets, to the extent treated as interest under GAAP, and the portion of rent expense under finance leases treated as interest under GAAP, of the Borrower and its Subsidiaries on a consolidated basis.'],
    ['Consolidated Net Income', 'means, for any period, the net income of the Borrower and its Subsidiaries on a consolidated basis, excluding extraordinary gains and losses, the income of any Subsidiary to the extent its distributions are restricted, and the income of any Person that is not a Subsidiary except to the extent of cash distributions actually received.'],
    ['Consolidated Total Leverage Ratio', 'means, as of any date of determination, the ratio of (a) Consolidated Funded Indebtedness as of that date, minus unrestricted cash and Cash Equivalents of the Loan Parties not exceeding $40,000,000, to (b) Consolidated EBITDA for the period of the four fiscal quarters most recently ended for which financial statements have been delivered.'],
    ['Control', 'means the possession, directly or indirectly, of the power to direct or cause the direction of the management or policies of a Person, whether through the ability to exercise voting power, by contract, or otherwise; "Controlling" and "Controlled" have meanings correlative thereto.'],
    ['Default Rate', 'means an interest rate equal to the interest rate otherwise applicable to the relevant Loan plus two percent per annum, or, for amounts for which no rate applies, the Base Rate plus the Applicable Rate for Base Rate Loans plus two percent per annum.'],
    ['Defaulting Lender', 'means any Lender that has failed to fund any portion of its Loans or participations within two Business Days of the date required, has notified the Borrower or the Administrative Agent that it does not intend to comply with its funding obligations, or has become the subject of a Bail-In Action or a proceeding under any Debtor Relief Law.'],
    ['Disposition', 'means the sale, transfer, license, lease, or other disposition of any property by any Person, including any sale, assignment, transfer, or other disposal of any notes or accounts receivable, with or without recourse.'],
    ['Eligible Assignee', 'means any Person that meets the requirements to be an assignee under Section 10.06(b), other than a natural person, a Defaulting Lender, or the Borrower or any of its Affiliates.'],
    ['Environmental Laws', 'means all federal, state, local, and foreign statutes, laws, regulations, ordinances, rules, judgments, orders, permits, and governmental restrictions relating to pollution, the protection of the environment, or the release of any materials into the environment.'],
    ['Event of Default', 'has the meaning specified in Section 8.01.'],
    ['Excluded Property', 'means (a) any fee-owned real property that is not Material Real Property and all leasehold interests; (b) motor vehicles subject to certificates of title; (c) Equity Interests in excess of 65% of the voting Equity Interests of any Foreign Subsidiary; (d) any lease, license, or contract to the extent a grant of a Lien would breach it; and (e) assets for which the cost of obtaining a security interest is excessive in relation to the benefit to the Lenders, as reasonably determined by the Administrative Agent.'],
    ['Existing Credit Agreement', `means the Credit Agreement dated as of ${longDate(existingDate)} among the Borrower, the lenders party thereto, and ${EXISTING_AGENT}, as administrative agent, as amended prior to the Closing Date.`],
    ['Facility', 'means the Term A Facility or the Revolving Credit Facility, as the context may require.'],
    ['Federal Funds Rate', 'means, for any day, the rate per annum calculated by the Federal Reserve Bank of New York based on the day\'s federal funds transactions by depository institutions, as published on the next succeeding Business Day as the federal funds effective rate; if that rate is less than zero, it is deemed to be zero.'],
    ['Fee Letter', `means the letter agreement dated May 8, 2026 among the Borrower, the Administrative Agent, and ${ARRANGERS[0]}.`],
    ['Foreign Subsidiary', 'means any Subsidiary that is organized under the laws of a jurisdiction other than the United States, a State thereof, or the District of Columbia.'],
    ['GAAP', 'means generally accepted accounting principles in the United States set forth in the opinions and pronouncements of the Financial Accounting Standards Board, consistently applied and as in effect from time to time, subject to Section 1.03.'],
    ['Guarantors', 'means, collectively, each Domestic Subsidiary of the Borrower that is a party to the Guaranty on the Closing Date as listed in Schedule 5.13, and each other Subsidiary that becomes a party to the Guaranty under Section 6.12.'],
    ['Incremental Facility', `has the meaning specified in Section 2.16, being one or more increases in the Revolving Credit Commitments or incremental term loans in an aggregate amount not to exceed the greater of $100,000,000 and 100% of Consolidated EBITDA, plus an additional amount so long as the Consolidated Total Leverage Ratio, on a Pro Forma Basis, does not exceed 3.00 to 1.00.`],
    ['Indebtedness', 'means, as to any Person at a particular time, without duplication: all obligations for borrowed money and obligations evidenced by bonds, debentures, notes, loan agreements, or similar instruments; the maximum amount available to be drawn under letters of credit, bankers\' acceptances, and similar instruments; net obligations under any Swap Contract; obligations to pay the deferred purchase price of property, other than trade accounts payable in the ordinary course not more than 90 days past due; Attributable Indebtedness; obligations to purchase or redeem Disqualified Equity Interests; and Guarantees of any of the foregoing.'],
    ['Interest Payment Date', 'means (a) as to any Term SOFR Loan, the last day of each Interest Period applicable to it and the applicable Maturity Date, provided that if an Interest Period exceeds three months, the respective dates that fall every three months after its beginning are also Interest Payment Dates; and (b) as to any Base Rate Loan or Swing Line Loan, the last Business Day of each March, June, September, and December and the applicable Maturity Date.'],
    ['Interest Period', 'means, as to each Term SOFR Loan, the period commencing on the date it is disbursed, converted, or continued and ending on the date one, three, or six months thereafter, as selected by the Borrower in its Committed Loan Notice; no Interest Period may extend beyond the Maturity Date of the applicable Facility.'],
    ['Investment', 'means, as to any Person, any direct or indirect acquisition or investment by that Person, whether by purchase of Equity Interests or debt securities, a loan or advance, a Guarantee of obligations of another Person, a capital contribution, or the purchase of property constituting a business unit, the amount of which is its original cost less any return of capital.'],
    ['L/C Issuer', `means ${AGENT}, in its capacity as issuer of Letters of Credit, and any other Lender that agrees with the Borrower and the Administrative Agent to issue Letters of Credit, each in its capacity as such.`],
    ['Letter of Credit Sublimit', 'means an amount equal to the lesser of $20,000,000 and the Revolving Credit Facility; the Letter of Credit Sublimit is part of, and not in addition to, the Revolving Credit Facility.'],
    ['Lien', 'means any mortgage, pledge, hypothecation, assignment, deposit arrangement, encumbrance, lien (statutory or other), charge, or preference, priority, or other security interest or preferential arrangement in the nature of a security interest of any kind, including the interest of a purchaser of accounts and any financing lease having substantially the same economic effect.'],
    ['Loan Documents', 'means this Agreement, each Note, the Guaranty, the Collateral Documents, the Fee Letter, each Issuer Document, and any agreement creating or perfecting rights in Cash Collateral.'],
    ['Material Adverse Effect', 'means (a) a material adverse change in, or a material adverse effect upon, the operations, business, assets, properties, liabilities, or condition (financial or otherwise) of the Borrower and its Subsidiaries taken as a whole; (b) a material impairment of the ability of the Loan Parties, taken as a whole, to perform their obligations under the Loan Documents; or (c) a material adverse effect upon the legality, validity, binding effect, or enforceability against any Loan Party of any Loan Document to which it is a party.'],
    ['Material Real Property', 'means any fee-owned real property of a Loan Party located in the United States with a fair market value in excess of $10,000,000, including on the Closing Date the plants at 2210 Marrowfield Road, Marrow Springs, Colorado and 18 Cinder Street, Linden Cross, Pennsylvania.'],
    ['Maturity Date', `means ${longDate(maturity)}; provided that if that date is not a Business Day, the Maturity Date is the immediately preceding Business Day.`],
    ['Net Cash Proceeds', 'means, with respect to any Asset Sale or casualty event, the excess of the cash proceeds received over the sum of the principal amount of any Indebtedness secured by a prior Lien on the asset and required to be repaid, reasonable out-of-pocket expenses incurred in connection with the transaction, and taxes reasonably estimated to be payable as a result of it.'],
    ['Obligations', 'means all advances to, and debts, liabilities, obligations, covenants, and duties of, any Loan Party arising under any Loan Document or otherwise with respect to any Loan, Letter of Credit, Secured Cash Management Agreement, or Secured Hedge Agreement, whether direct or indirect, absolute or contingent, due or to become due, now existing or hereafter arising.'],
    ['Permitted Acquisition', 'means an Acquisition by the Borrower or a Subsidiary in which (a) no Event of Default exists or would result; (b) the target is in a line of business permitted by Section 7.07; (c) the Acquisition is not hostile; (d) on a Pro Forma Basis the Consolidated Total Leverage Ratio does not exceed 0.25 less than the maximum then permitted by Section 7.11(a); and (e) for consideration exceeding $50,000,000, the Borrower delivers to the Administrative Agent at least five Business Days before closing a certificate demonstrating compliance with this definition.'],
    ['Pro Forma Basis', 'means, for purposes of calculating compliance with any test, that the relevant transaction and any related incurrence or repayment of Indebtedness are deemed to have occurred on the first day of the relevant measurement period, with historical financial results of an acquired business included and those of a disposed business excluded.'],
    ['Required Lenders', 'means, as of any date of determination, Lenders holding more than 50% of the sum of the Total Outstandings (with the aggregate amount of each Lender\'s participation in L/C Obligations and Swing Line Loans deemed held by that Lender) and the aggregate unused Commitments; the Commitments and Outstandings of any Defaulting Lender are disregarded.'],
    ['Responsible Officer', 'means the chief executive officer, president, chief financial officer, treasurer, or assistant treasurer of a Loan Party, and, solely for purposes of notices given under Article II, any other officer designated in writing by any of the foregoing and delivered to the Administrative Agent.'],
    ['Restricted Payment', 'means any dividend or other distribution with respect to any Equity Interest of the Borrower or any Subsidiary, or any payment on account of the purchase, redemption, retirement, acquisition, cancellation, or termination of any such Equity Interest, or any option, warrant, or other right to acquire any such Equity Interest.'],
    ['Revolving Credit Facility', `means, at any time, the aggregate amount of the Revolving Credit Lenders' Revolving Credit Commitments at that time, which on the Closing Date is ${money(revolving, { cents: false })}.`],
    ['Sanctions', 'means any sanction administered or enforced by the United States Government (including the Office of Foreign Assets Control), the United Nations Security Council, the European Union, His Majesty\'s Treasury, or any other relevant sanctions authority.'],
    ['Secured Parties', 'means, collectively, the Administrative Agent, the Lenders, the L/C Issuer, the Hedge Banks, the Cash Management Banks, each co-agent or sub-agent appointed by the Administrative Agent, and the other Persons the Obligations owing to which are secured by the Collateral.'],
    ['Security Agreement', 'means the Pledge and Security Agreement dated as of the Closing Date among the Loan Parties and the Administrative Agent.'],
    ['SOFR', 'means the secured overnight financing rate published by the Federal Reserve Bank of New York, as the administrator of the benchmark, or a successor administrator.'],
    ['Solvent', 'means, with respect to any Person on any date, that on that date the fair value of its property is greater than the total amount of its liabilities, including contingent liabilities; it is able to pay its debts as they mature; and it does not have unreasonably small capital with which to conduct its business.'],
    ['Swing Line Sublimit', 'means an amount equal to the lesser of $10,000,000 and the Revolving Credit Facility; the Swing Line Sublimit is part of, and not in addition to, the Revolving Credit Facility.'],
    ['Term A Facility', `means, at any time, (a) on or prior to the Closing Date, the aggregate amount of the Term A Commitments, which on the Closing Date is ${money(termA, { cents: false })}, and (b) thereafter, the aggregate principal amount of the Term A Loans of all Term A Lenders outstanding at that time.`],
    ['Term SOFR', 'means, for any Interest Period, the forward-looking term rate based on SOFR for a tenor comparable to that Interest Period as published two U.S. Government Securities Business Days before its first day, plus a credit spread adjustment of 0.10% per annum; if Term SOFR would be less than zero, it is deemed to be zero.'],
    ['Threshold Amount', `means ${threshold}.`],
    ['Total Outstandings', 'means the aggregate Outstanding Amount of all Loans and all L/C Obligations.'],
    ['Type', 'means, with respect to a Loan, its character as a Base Rate Loan or a Term SOFR Loan.'],
  ];
}

function creditArticles({ closing, maturity, firstTest, revolving, termA, rng }) {
  const amortization = [];
  let date = firstTest;
  for (let quarter = 0; quarter < 19; quarter += 1) {
    // Thousandths of a percent: 1.250%, then 1.875%, then 2.500% a quarter.
    const percent = quarter < 8 ? 1250 : quarter < 12 ? 1875 : 2500;
    amortization.push([longDate(date), `${decimal(percent, 3)}%`, money(Math.round((termA * percent) / 100000))]);
    date = endOfMonth(addMonths(date, 3));
  }
  return [
    ['The Commitments and Credit Extensions', [
      ['Term A Loans', `Subject to the terms and conditions set forth herein, each Term A Lender severally agrees to make a single loan to the Borrower on the Closing Date in an amount not to exceed its Term A Commitment. The Term A Borrowing shall consist of Term A Loans made simultaneously by the Term A Lenders in accordance with their respective Applicable Percentages of the Term A Facility, which in the aggregate shall equal ${money(termA, { cents: false })}. Amounts borrowed under this Section and repaid or prepaid may not be reborrowed.`],
      ['Revolving Credit Loans', `Subject to the terms and conditions set forth herein, each Revolving Credit Lender severally agrees to make loans to the Borrower from time to time, on any Business Day during the Availability Period, in an aggregate amount not to exceed at any time outstanding its Revolving Credit Commitment; provided that after giving effect to any Revolving Credit Borrowing, the Total Revolving Credit Outstandings shall not exceed ${money(revolving, { cents: false })}. Within these limits the Borrower may borrow, prepay, and reborrow.`],
      ['Borrowings, Conversions, and Continuations', 'Each Borrowing, each conversion of Loans from one Type to the other, and each continuation of Term SOFR Loans shall be made upon the Borrower\'s irrevocable notice to the Administrative Agent, which must be received by the Administrative Agent not later than 11:00 a.m. three Business Days prior to the requested date of any Borrowing of, conversion to, or continuation of Term SOFR Loans, and on the requested date of any Borrowing of Base Rate Loans. Each Borrowing of Term SOFR Loans shall be in a principal amount of $2,000,000 or a whole multiple of $1,000,000 in excess thereof, and not more than eight Interest Periods may be in effect at any time.'],
      ['Letters of Credit', 'Subject to the terms and conditions set forth herein, the L/C Issuer agrees, in reliance upon the agreements of the Revolving Credit Lenders set forth in this Section, to issue standby and commercial letters of credit for the account of the Borrower or its Subsidiaries, and to amend or extend Letters of Credit previously issued by it, provided that after giving effect to any such issuance the Outstanding Amount of the L/C Obligations shall not exceed the Letter of Credit Sublimit. No Letter of Credit shall have an expiry date later than the earlier of twelve months after its issuance and seven days before the Maturity Date.', [
        'Each Revolving Credit Lender irrevocably purchases from the L/C Issuer a risk participation in each Letter of Credit in an amount equal to its Applicable Percentage of the amount of that Letter of Credit.',
        'If any drawing is paid under a Letter of Credit, the Borrower shall reimburse the L/C Issuer not later than 11:00 a.m. on the Business Day following notice of the drawing, failing which the unreimbursed amount is deemed a request for a Revolving Credit Borrowing of Base Rate Loans.',
        'The Borrower shall pay a Letter of Credit fee at the Applicable Rate on the daily amount available to be drawn, quarterly in arrears, and a fronting fee of 0.125% per annum to the L/C Issuer for its own account.',
      ]],
      ['Swing Line Loans', 'Subject to the terms and conditions set forth herein, the Swing Line Lender may in its sole discretion make loans to the Borrower from time to time on any Business Day during the Availability Period in an aggregate amount not to exceed at any time outstanding the Swing Line Sublimit. Each Swing Line Loan shall be a Base Rate Loan, shall be in a minimum amount of $250,000, and shall be repaid on the earlier of ten Business Days after it is made and the Maturity Date.'],
      ['Prepayments', 'The Borrower may, upon notice to the Administrative Agent, at any time voluntarily prepay Loans in whole or in part without premium or penalty, subject to Section 3.05 (breakage). In addition, the Borrower shall prepay the Term A Loans:', [
        'within five Business Days after receipt of Net Cash Proceeds of any Asset Sale or casualty event in excess of $15,000,000 in any fiscal year, in an amount equal to 100% of those Net Cash Proceeds, unless reinvested in assets used in the business within 365 days (or committed to be reinvested within that period and reinvested within 180 days thereafter);',
        'within three Business Days after the incurrence of any Indebtedness not permitted by Section 7.02, in an amount equal to 100% of the net cash proceeds thereof; and',
        'if for any reason the Total Revolving Credit Outstandings at any time exceed the Revolving Credit Facility, immediately, in an aggregate amount equal to the excess, by prepaying Revolving Credit Loans and Swing Line Loans and, if necessary, Cash Collateralizing L/C Obligations.',
      ]],
      ['Termination or Reduction of Commitments', 'The Borrower may, upon notice to the Administrative Agent not later than 11:00 a.m. five Business Days prior to the date of termination or reduction, terminate the Revolving Credit Facility or from time to time permanently reduce it in an aggregate amount of $5,000,000 or any whole multiple of $1,000,000 in excess thereof, provided that the Revolving Credit Facility shall not be reduced below the Total Revolving Credit Outstandings.'],
      ['Repayment of Loans', `The Borrower shall repay to the Term A Lenders the aggregate principal amount of all Term A Loans outstanding in quarterly installments on the last Business Day of each March, June, September, and December, commencing with the fiscal quarter ending ${longDate(firstTest)}, in the percentages of the original principal amount set out below, with the remaining balance due on the Maturity Date. The Borrower shall repay to the Revolving Credit Lenders on the Maturity Date the aggregate principal amount of all Revolving Credit Loans outstanding on that date.`, [], {
        columns: [{ header: 'Installment date', width: 0.4 }, { header: 'Percentage of original principal', width: 0.3, align: 'right' }, { header: 'Installment', width: 0.3, align: 'right' }],
        rows: amortization,
      }],
      ['Interest', 'Each Term SOFR Loan shall bear interest on the outstanding principal amount thereof for each Interest Period at a rate per annum equal to Term SOFR for that Interest Period plus the Applicable Rate; each Base Rate Loan shall bear interest from the date of borrowing at a rate per annum equal to the Base Rate plus the Applicable Rate; and each Swing Line Loan shall bear interest at the Base Rate plus the Applicable Rate for Revolving Credit Loans. While any Event of Default under Section 8.01(a) or (f) exists, all Obligations shall bear interest at the Default Rate.'],
      ['Fees', 'The Borrower shall pay to the Administrative Agent for the account of each Revolving Credit Lender a commitment fee equal to the Applicable Rate times the actual daily amount by which the Revolving Credit Facility exceeds the Total Revolving Credit Outstandings, payable quarterly in arrears on the last Business Day of each March, June, September, and December. The Borrower shall also pay the fees in the amounts and at the times specified in the Fee Letter.'],
      ['Computation of Interest and Fees', 'All computations of interest for Base Rate Loans when the Base Rate is determined by the prime rate shall be made on the basis of a year of 365 or 366 days and actual days elapsed; all other computations of fees and interest shall be made on the basis of a 360-day year and actual days elapsed.'],
      ['Payments Generally', 'All payments by the Borrower shall be made without condition or deduction for any counterclaim, defense, recoupment, or setoff, to the Administrative Agent for the account of the respective Lenders at the Administrative Agent\'s Office in Dollars and in immediately available funds not later than 2:00 p.m. on the date specified herein. All payments received after that time shall be deemed received on the next succeeding Business Day.'],
      ['Evidence of Debt', 'The Credit Extensions made by each Lender shall be evidenced by one or more accounts or records maintained by that Lender and by the Administrative Agent in the ordinary course of business. The accounts or records maintained by the Administrative Agent and each Lender are conclusive absent manifest error of the amount of the Credit Extensions made by the Lenders to the Borrower and the interest and payments thereon. Upon the request of any Lender made through the Administrative Agent, the Borrower shall execute and deliver to that Lender a Note in the form of Exhibit D.'],
      ['Sharing of Payments by Lenders', 'If any Lender shall obtain payment in respect of any principal of or interest on any of its Loans or participations resulting in its receiving a greater proportion of the aggregate amount than its pro rata share, it shall purchase participations in the Loans and participations of the other Lenders so that the benefit of all such payments is shared by the Lenders ratably.'],
      ['Incremental Facilities', `At any time after the Closing Date and before the Maturity Date, the Borrower may by written notice to the Administrative Agent request one or more Incremental Facilities, each in a minimum amount of $25,000,000. Any incremental term loans shall rank pari passu in right of payment and security with the Term A Loans, shall not mature earlier than the Maturity Date, and, if the all-in yield exceeds that of the Term A Loans by more than 0.50%, the Applicable Rate for the Term A Loans shall be increased to eliminate the excess.`],
      ['Cash Collateral', 'At any time that there exists a Defaulting Lender, within one Business Day following the written request of the Administrative Agent or the L/C Issuer, the Borrower shall Cash Collateralize the L/C Issuer\'s Fronting Exposure with respect to that Defaulting Lender in an amount not less than the Minimum Collateral Amount. The Borrower grants to the Administrative Agent, for the benefit of the L/C Issuer, a first priority security interest in all such Cash Collateral and all proceeds thereof.'],
      ['Extension of Maturity Date', 'Not earlier than 60 days nor later than 30 days prior to any anniversary of the Closing Date, the Borrower may request that each Lender extend the Maturity Date applicable to its Commitments and Loans for an additional one year. Each Lender may agree or decline in its sole discretion, and the extension becomes effective only if Lenders holding more than 50% of the Aggregate Commitments agree, in which case the Commitments of each non-extending Lender terminate on its existing Maturity Date and the Borrower may replace it with one or more Eligible Assignees.'],
      ['Defaulting Lenders', 'Notwithstanding anything to the contrary, if any Lender becomes a Defaulting Lender, then for so long as it is a Defaulting Lender its Commitments and Outstandings shall be excluded in determining the Required Lenders, payments to it shall be applied first to amounts owing to the Administrative Agent, the L/C Issuer, and the Swing Line Lender, and its participation in L/C Obligations and Swing Line Loans shall be reallocated among the non-Defaulting Lenders to the extent their Revolving Credit Exposure would not exceed their Commitments.'],
    ]],
    ['Taxes, Yield Protection, and Illegality', [
      ['Taxes', 'Any and all payments by or on account of any obligation of any Loan Party shall be made without deduction or withholding for any Taxes, except as required by applicable law. If any applicable law requires the deduction or withholding of any Indemnified Taxes, the sum payable by the Loan Party shall be increased as necessary so that after any required withholding the applicable Recipient receives an amount equal to the sum it would have received had no such withholding been made. Each Lender shall deliver to the Borrower and the Administrative Agent the applicable Internal Revenue Service forms establishing any exemption from withholding.'],
      ['Illegality', 'If any Lender determines that any law has made it unlawful for it to make, maintain, or fund Loans whose interest is determined by reference to SOFR or Term SOFR, then its obligation to make or continue Term SOFR Loans shall be suspended until the circumstances giving rise to the determination no longer exist, and the Borrower shall, if necessary to avoid the illegality, convert all such Loans of that Lender to Base Rate Loans.'],
      ['Inability to Determine Rates', 'If the Administrative Agent determines that Term SOFR cannot be determined for any requested Interest Period, or the Required Lenders determine that Term SOFR does not adequately reflect the cost to the Lenders of funding the Loans, the obligation of the Lenders to make or continue Term SOFR Loans shall be suspended, and any pending request shall be deemed a request for Base Rate Loans, until a Benchmark Replacement is implemented in accordance with this Article.'],
      ['Increased Costs', 'If any Change in Law shall impose any reserve, special deposit, liquidity, or similar requirement against assets of any Lender, subject any Recipient to any Taxes other than Indemnified Taxes and Excluded Taxes, or impose any other condition affecting this Agreement, and the result is to increase the cost to the Lender of making or maintaining any Loan or to reduce the amount received by it, the Borrower will pay to the Lender such additional amounts as will compensate it for the additional costs incurred or reduction suffered, upon delivery of a certificate setting forth the amount in reasonable detail.'],
      ['Compensation for Losses', 'Upon demand of any Lender, the Borrower shall promptly compensate that Lender for any loss, cost, or expense incurred by it as a result of any continuation, conversion, payment, or prepayment of any Term SOFR Loan on a day other than the last day of its Interest Period, or any failure by the Borrower to borrow, continue, or convert a Term SOFR Loan on the date specified in its notice, excluding loss of anticipated profits.'],
      ['Mitigation; Replacement of Lenders', 'If any Lender requests compensation under Section 3.04, or the Borrower is required to pay additional amounts to a Lender under Section 3.01, that Lender shall use reasonable efforts to designate a different lending office if doing so would eliminate or reduce the amounts payable; if it does not, the Borrower may replace that Lender with an Eligible Assignee in accordance with Section 10.13.'],
    ]],
    ['Conditions Precedent to Credit Extensions', [
      ['Conditions of Initial Credit Extension', 'The obligation of the L/C Issuer and each Lender to make its initial Credit Extension hereunder is subject to satisfaction of the following conditions precedent:', [
        'receipt by the Administrative Agent of executed counterparts of this Agreement, the Guaranty, the Security Agreement, and the Notes requested by Lenders, each properly executed by a Responsible Officer of the signing Loan Party;',
        'receipt of certificates of resolutions, incumbency certificates, organizational documents, and good standing certificates for each Loan Party;',
        'receipt of favorable opinions of Kilbride Moncrieff LLP, counsel to the Loan Parties, addressed to the Administrative Agent and each Lender;',
        'receipt of a solvency certificate signed by the chief financial officer of the Borrower, certifying that the Loan Parties, taken as a whole, are Solvent after giving effect to the transactions to occur on the Closing Date;',
        'evidence that all indebtedness under the Existing Credit Agreement has been or concurrently with the Closing Date is being paid in full, all commitments thereunder terminated, and all Liens securing it released;',
        'UCC, tax lien, and judgment searches, and the filing of UCC financing statements in each jurisdiction necessary to perfect the Liens granted under the Collateral Documents;',
        'payment of all fees required to be paid on or before the Closing Date under the Fee Letter, and all reasonable out-of-pocket expenses of the Administrative Agent invoiced at least two Business Days before the Closing Date; and',
        'receipt of all documentation and other information required by regulatory authorities under applicable "know your customer" and anti-money-laundering rules, including a Beneficial Ownership Certification.',
      ]],
      ['Conditions to All Credit Extensions', 'The obligation of each Lender to honor any request for a Credit Extension is subject to the conditions that the representations and warranties of each Loan Party contained in Article V or any other Loan Document are true and correct in all material respects on and as of the date of the Credit Extension, except to the extent they specifically refer to an earlier date; no Default exists or would result from the proposed Credit Extension; and the Administrative Agent has received a request for Credit Extension in accordance with the requirements hereof.'],
    ]],
    ['Representations and Warranties', [
      ['Existence, Qualification, and Power', 'Each Loan Party and each Subsidiary is duly organized or formed, validly existing, and in good standing under the laws of the jurisdiction of its incorporation or organization, has all requisite power and authority to own its assets and carry on its business, and is duly qualified and in good standing in each jurisdiction where its ownership of property or conduct of business requires such qualification, except where failure to be so qualified could not reasonably be expected to have a Material Adverse Effect.'],
      ['Authorization; No Contravention', 'The execution, delivery, and performance by each Loan Party of each Loan Document to which it is party have been duly authorized by all necessary corporate or other organizational action and do not contravene its Organization Documents, conflict with or result in any breach of any Contractual Obligation to which it is a party, or violate any law.'],
      ['Financial Statements; No Material Adverse Effect', 'The Audited Financial Statements were prepared in accordance with GAAP consistently applied throughout the period covered and fairly present the financial condition of the Borrower and its Subsidiaries as of the date thereof and their results of operations for the period covered. Since December 31, 2025, there has been no event or circumstance that has had or could reasonably be expected to have a Material Adverse Effect.'],
      ['Litigation', 'There are no actions, suits, proceedings, claims, or disputes pending or, to the knowledge of the Borrower, threatened against the Borrower or any Subsidiary that purport to affect any Loan Document or that could reasonably be expected to have a Material Adverse Effect. The pending wage-and-hour class action against Marrowfield Flexibles LLC in Ohio, in which damages of not more than $4,200,000 are claimed, is not reasonably expected to have a Material Adverse Effect.'],
      ['Ownership of Property; Liens', 'Each Loan Party has good record and marketable title in fee simple to, or valid leasehold interests in, all real property necessary in the ordinary conduct of its business. The property of the Borrower and its Subsidiaries is subject to no Liens other than Liens permitted by Section 7.01.'],
      ['Environmental Compliance', 'The Borrower and its Subsidiaries conduct in the ordinary course of business a review of the effect of existing Environmental Laws on their businesses and properties, and on the basis of that review the Borrower has reasonably concluded that existing Environmental Laws and claims could not reasonably be expected to have a Material Adverse Effect. The remediation of solvent contamination at the Linden Cross plant is being conducted under a consent order with a projected remaining cost of $1,350,000, fully reserved.'],
      ['Insurance', 'The properties of the Borrower and its Subsidiaries are insured with financially sound and reputable insurance companies not Affiliates of the Borrower, in such amounts, with such deductibles, and covering such risks as are customarily carried by companies engaged in similar businesses and owning similar properties in localities where the Borrower or the applicable Subsidiary operates; the Borrower\'s captive insurer reinsures only the first $500,000 of each workers\' compensation claim.'],
      ['Taxes', 'The Borrower and its Subsidiaries have filed all federal, state, and other material tax returns and reports required to be filed, and have paid all federal, state, and other material taxes levied upon them or their properties, income, or assets otherwise due and payable, except those being contested in good faith by appropriate proceedings for which adequate reserves have been provided in accordance with GAAP.'],
      ['ERISA Compliance', 'Each Plan is in compliance in all material respects with the applicable provisions of ERISA, the Code, and other federal or state laws. No ERISA Event has occurred, and the Borrower\'s only defined benefit pension plan, frozen since 2017, was funded at 94% of its funding target on the most recent valuation date.'],
      ['Subsidiaries; Equity Interests', 'As of the Closing Date, the Borrower has no Subsidiaries other than those specifically disclosed in Schedule 5.13, and all of the outstanding Equity Interests in those Subsidiaries have been validly issued, are fully paid and non-assessable, and are owned by a Loan Party in the amounts specified on Schedule 5.13 free and clear of all Liens except those created under the Collateral Documents.'],
      ['Margin Regulations; Investment Company Act', 'The Borrower is not engaged principally in the business of purchasing or carrying margin stock, and no proceeds of any Borrowing will be used for that purpose. Neither the Borrower nor any Subsidiary is required to be registered as an "investment company" under the Investment Company Act of 1940.'],
      ['Solvency', 'The Loan Parties, on a consolidated basis, are Solvent, both before and after giving effect to the transactions contemplated by the Loan Documents to occur on the Closing Date.'],
      ['Sanctions; Anti-Corruption', 'Neither the Borrower nor any Subsidiary, nor to the knowledge of the Borrower any director, officer, or employee thereof, is an individual or entity that is the subject of any Sanctions or located in a Designated Jurisdiction. The Borrower and its Subsidiaries have conducted their businesses in compliance in all material respects with applicable anti-corruption laws and have instituted policies designed to promote compliance with them.'],
    ]],
    ['Affirmative Covenants', [
      ['Financial Statements', 'The Borrower shall deliver to the Administrative Agent for distribution to each Lender (a) as soon as available, and in any event within 90 days after the end of each fiscal year, a consolidated balance sheet of the Borrower and its Subsidiaries as at the end of that fiscal year and the related consolidated statements of income, changes in shareholders\' equity, and cash flows, audited and accompanied by a report and opinion of an independent certified public accountant of nationally recognized standing not subject to any "going concern" qualification; and (b) within 45 days after the end of each of the first three fiscal quarters, the corresponding unaudited consolidated statements, certified by a Responsible Officer.'],
      ['Certificates; Other Information', 'Concurrently with the delivery of the financial statements under Section 6.01, the Borrower shall deliver a duly completed Compliance Certificate signed by its chief financial officer, and, within 60 days after the beginning of each fiscal year, an annual budget of the Borrower and its Subsidiaries on a consolidated basis, including forecasts of balance sheets, income statements, and cash flow statements for that fiscal year on a quarterly basis.'],
      ['Notices', 'The Borrower shall promptly notify the Administrative Agent of the occurrence of any Default; of any matter that has resulted or could reasonably be expected to result in a Material Adverse Effect; of the occurrence of any ERISA Event; of any material change in accounting policies or financial reporting practices; and of any announcement by a rating agency of any change in a debt rating of the Borrower.'],
      ['Payment of Obligations', 'The Borrower shall, and shall cause each Subsidiary to, pay and discharge as the same become due and payable all tax liabilities, assessments, and governmental charges upon it or its properties, and all lawful claims that, if unpaid, would by law become a Lien upon its property, unless contested in good faith by appropriate proceedings with adequate reserves.'],
      ['Preservation of Existence', 'The Borrower shall, and shall cause each Subsidiary to, preserve, renew, and maintain in full force and effect its legal existence and good standing under the laws of the jurisdiction of its organization, except in a transaction permitted by Section 7.04 or 7.05, and take all reasonable action to maintain all rights, privileges, permits, licenses, and franchises necessary or desirable in the normal conduct of its business.'],
      ['Maintenance of Properties and Insurance', 'The Borrower shall maintain all of its material properties and equipment necessary in the operation of its business in good working order and condition, ordinary wear and tear excepted, and shall maintain insurance in accordance with Section 5.10, naming the Administrative Agent as additional insured and lender loss payee, with thirty days\' notice of cancellation.'],
      ['Books and Records; Inspection Rights', 'The Borrower shall maintain proper books of record and account and shall permit representatives of the Administrative Agent to visit and inspect its properties, examine its corporate, financial, and operating records, and discuss its affairs with its directors, officers, and independent accountants, not more than once per fiscal year at the Borrower\'s expense while no Event of Default exists.'],
      ['Compliance with Laws', 'The Borrower shall comply in all respects with the requirements of all laws and all orders, writs, injunctions, and decrees applicable to it or to its business or property, except where the requirement is being contested in good faith or where failure to comply could not reasonably be expected to have a Material Adverse Effect, and shall maintain in effect policies designed to promote compliance by the Borrower, its Subsidiaries, and their directors, officers, and employees with Anti-Corruption Laws and Sanctions.'],
      ['Environmental Matters', 'The Borrower shall, and shall cause each Subsidiary to, comply in all material respects with all Environmental Laws, obtain and renew all environmental permits necessary for its operations, and conduct any investigation, study, sampling, testing, remedial, or other corrective action required under Environmental Laws, including completion of the remediation at the Linden Cross plant in accordance with the consent order and the schedule approved by the state environmental agency.'],
      ['Use of Proceeds', 'The Borrower shall use the proceeds of the Credit Extensions to refinance the Existing Credit Agreement on the Closing Date, to pay fees and expenses in connection with this Agreement, and for working capital, Capital Expenditures, Permitted Acquisitions, Restricted Payments permitted hereunder, and other general corporate purposes not in contravention of any law or any Loan Document.'],
      ['Post-Closing Obligations', 'The Borrower shall deliver, or cause to be delivered, to the Administrative Agent the following, each in form and substance reasonably satisfactory to the Administrative Agent, within the time periods specified (or such later dates as the Administrative Agent may agree in its sole discretion): (a) within 30 days after the Closing Date, deposit account control agreements for each deposit account of a Loan Party other than Excluded Accounts; (b) within 60 days after the Closing Date, insurance endorsements naming the Administrative Agent as additional insured and lender loss payee; and (c) within 90 days after the Closing Date, a Mortgage, title insurance policy, survey, flood determination, and local counsel opinion for each Material Real Property.'],
      ['Additional Guarantors and Collateral', 'Within 45 days after any Person becomes a Domestic Subsidiary (other than an Excluded Subsidiary), or any Domestic Subsidiary ceases to be an Excluded Subsidiary, the Borrower shall cause that Person to become a Guarantor by executing a joinder to the Guaranty and the Security Agreement and to deliver the documents, opinions, and filings the Administrative Agent reasonably requests to perfect the Liens on its property.'],
    ]],
    ['Negative Covenants', [
      ['Liens', 'The Borrower shall not, nor shall it permit any Subsidiary to, create, incur, assume, or suffer to exist any Lien upon any of its property, whether now owned or hereafter acquired, other than the following:', [
        'Liens pursuant to any Loan Document;',
        'Liens existing on the Closing Date and listed on Schedule 7.01 and any renewals or extensions thereof, provided the property covered is not changed and the amount secured is not increased;',
        'Liens for taxes not yet due or being contested in good faith, and carriers\', warehousemen\'s, mechanics\', and similar Liens arising in the ordinary course for amounts not overdue for more than 30 days;',
        'Liens securing purchase money Indebtedness and Attributable Indebtedness permitted by Section 7.02(e), provided they do not extend to any property other than the property acquired with that Indebtedness;',
        'Liens on property of Foreign Subsidiaries securing Indebtedness of Foreign Subsidiaries permitted by Section 7.02(g); and',
        'other Liens securing obligations in an aggregate amount not to exceed the greater of $20,000,000 and 15% of Consolidated EBITDA at any time outstanding.',
      ]],
      ['Indebtedness', 'The Borrower shall not, nor shall it permit any Subsidiary to, create, incur, assume, or suffer to exist any Indebtedness, except: (a) Indebtedness under the Loan Documents; (b) Indebtedness outstanding on the Closing Date and listed on Schedule 7.02 and refinancings thereof not increasing the principal amount; (c) intercompany Indebtedness permitted as an Investment; (d) obligations under Swap Contracts entered into to hedge actual exposures and not for speculation; (e) purchase money Indebtedness and Attributable Indebtedness not exceeding the greater of $35,000,000 and 25% of Consolidated EBITDA; (f) unsecured Indebtedness so long as the Consolidated Total Leverage Ratio on a Pro Forma Basis does not exceed 3.25 to 1.00 and it matures at least 91 days after the Maturity Date; and (g) Indebtedness of Foreign Subsidiaries not exceeding $25,000,000 at any time outstanding.'],
      ['Investments', 'The Borrower shall not, nor shall it permit any Subsidiary to, make any Investments, except Investments held in the form of Cash Equivalents; advances to officers, directors, and employees not exceeding $1,500,000 at any time outstanding; Investments by Loan Parties in other Loan Parties; Investments by Loan Parties in Subsidiaries that are not Loan Parties not exceeding the greater of $30,000,000 and 20% of Consolidated EBITDA; Permitted Acquisitions; Investments in the Basalt Drive Inks joint venture not exceeding $8,000,000 in any fiscal year; and other Investments not exceeding the Available Amount.'],
      ['Fundamental Changes', 'The Borrower shall not, nor shall it permit any Subsidiary to, merge, dissolve, liquidate, consolidate with or into another Person, or Dispose of all or substantially all of its assets, except that any Subsidiary may merge with the Borrower (if the Borrower is the continuing Person) or with any other Subsidiary (if a Loan Party is the continuing Person when a Loan Party is involved), and any Subsidiary may Dispose of all or substantially all its assets to the Borrower or another Loan Party.'],
      ['Dispositions', 'The Borrower shall not, nor shall it permit any Subsidiary to, make any Disposition except Dispositions of obsolete or worn-out property, inventory in the ordinary course, equipment exchanged for similar replacement property, property to a Loan Party, licenses of intellectual property in the ordinary course, and other Dispositions for fair market value, at least 75% in cash, so long as the aggregate book value of all property so Disposed of in any fiscal year does not exceed 10% of consolidated total assets.'],
      ['Restricted Payments', 'The Borrower shall not, nor shall it permit any Subsidiary to, declare or make any Restricted Payment, except that each Subsidiary may make Restricted Payments to the Borrower and to other Loan Parties; the Borrower may declare and make dividends payable solely in its common stock; the Borrower may repurchase stock from former employees in an amount not to exceed $5,000,000 in any fiscal year; and the Borrower may make other Restricted Payments so long as no Event of Default exists and the Consolidated Total Leverage Ratio on a Pro Forma Basis does not exceed 2.75 to 1.00, or in an amount not exceeding the Available Amount.'],
      ['Change in Nature of Business', 'The Borrower shall not, nor shall it permit any Subsidiary to, engage in any material line of business substantially different from those lines of business conducted by the Borrower and its Subsidiaries on the Closing Date - the manufacture and sale of corrugated, folding carton, flexible, molded fiber, and label packaging and related printing, inks, and services - or any business substantially related, complementary, or incidental thereto.'],
      ['Transactions with Affiliates', 'The Borrower shall not, nor shall it permit any Subsidiary to, enter into any transaction of any kind with any Affiliate of the Borrower, whether or not in the ordinary course of business, other than on fair and reasonable terms substantially as favorable to the Borrower or the Subsidiary as would be obtainable in a comparable arm\'s length transaction with a Person other than an Affiliate, except transactions among Loan Parties and Restricted Payments permitted by Section 7.06.'],
      ['Burdensome Agreements', 'The Borrower shall not, nor shall it permit any Subsidiary to, enter into any Contractual Obligation that limits the ability of any Subsidiary to make Restricted Payments to the Borrower or any Guarantor, of any Subsidiary to Guarantee the Obligations, or of the Borrower or any Subsidiary to create Liens on its property in favor of the Administrative Agent, other than customary restrictions in joint venture agreements and in agreements governing purchase money Indebtedness.'],
      ['Use of Proceeds', 'The Borrower shall not use the proceeds of any Credit Extension, whether directly or indirectly, to purchase or carry margin stock, or to fund any activity or business of or with any Person that is the subject of Sanctions or in any Designated Jurisdiction, or in violation of any anti-corruption law.'],
      ['Sale and Leaseback Transactions', 'The Borrower shall not, nor shall it permit any Subsidiary to, enter into any arrangement whereby it sells or transfers any property, real or personal, used or useful in its business, and thereafter rents or leases that property or other property that it intends to use for substantially the same purpose, except sale-leaseback transactions involving property with an aggregate fair market value not exceeding $25,000,000 over the term of this Agreement, the Attributable Indebtedness of which is permitted under Section 7.02(e).'],
      ['Prepayments of Other Indebtedness', 'The Borrower shall not, nor shall it permit any Subsidiary to, prepay, redeem, purchase, defease, or otherwise satisfy prior to scheduled maturity any unsecured or subordinated Indebtedness, except refinancings permitted by Section 7.02, prepayments made with the net cash proceeds of Qualified Equity Interests, and other prepayments not exceeding the Available Amount so long as no Event of Default exists and the Consolidated Total Leverage Ratio on a Pro Forma Basis does not exceed 3.00 to 1.00.'],
      ['Amendments of Organization Documents; Fiscal Year', 'The Borrower shall not amend any of its Organization Documents in a manner materially adverse to the Lenders, and shall not change its fiscal year, which ends on December 31, without the consent of the Administrative Agent, provided that the Borrower may change its fiscal year upon notice, in which case the Borrower and the Administrative Agent will make any adjustments to this Agreement necessary to reflect the change.'],
      ['Financial Covenants', 'The Borrower shall not permit:', [
        `the Consolidated Total Leverage Ratio as of the end of any fiscal quarter, commencing with the fiscal quarter ending ${longDate(firstTest)}, to be greater than 3.75 to 1.00 for the fiscal quarters ending on or before June 30, 2027, and 3.50 to 1.00 thereafter; provided that the Borrower may elect, by notice with the Compliance Certificate for the quarter in which a Permitted Acquisition with consideration of $75,000,000 or more is consummated, to increase the maximum ratio by 0.50 for that quarter and the three following quarters, not more than twice during the term of this Agreement; or`,
        'the Consolidated Fixed Charge Coverage Ratio as of the end of any fiscal quarter to be less than 1.25 to 1.00.',
      ]],
    ]],
    ['Events of Default and Remedies', [
      ['Events of Default', 'Any of the following shall constitute an Event of Default:', [
        'the Borrower fails to pay when due any amount of principal of any Loan or L/C Obligation, or within three Business Days after the same becomes due, any interest, fee, or other amount payable hereunder;',
        'the Borrower fails to perform or observe any term, covenant, or agreement contained in Section 6.03(a), 6.05(a), or 6.11 or Article VII;',
        'any Loan Party fails to perform or observe any other covenant contained in any Loan Document and the failure continues for 30 days after notice from the Administrative Agent;',
        'any representation or warranty made by any Loan Party proves to have been incorrect or misleading in any material respect when made;',
        'the Borrower or any Subsidiary fails to make any payment when due in respect of any Indebtedness having an aggregate principal amount of more than the Threshold Amount, or any event occurs the effect of which is to cause or permit that Indebtedness to become due before its stated maturity;',
        'the Borrower or any Subsidiary institutes or consents to the institution of any proceeding under any Debtor Relief Law, or makes a general assignment for the benefit of creditors, or any such proceeding instituted against it continues undismissed for 60 calendar days;',
        'one or more final judgments for the payment of money in an aggregate amount exceeding the Threshold Amount (to the extent not covered by insurance as to which the insurer has not disputed coverage) is entered against the Borrower or any Subsidiary and is not discharged or stayed for 30 consecutive days;',
        'an ERISA Event occurs which has resulted or could reasonably be expected to result in liability of the Borrower in an aggregate amount in excess of the Threshold Amount;',
        'any Loan Document ceases to be in full force and effect, or any Lien purported to be created by any Collateral Document ceases to be a valid and perfected Lien on Collateral with a fair market value in excess of $10,000,000; or',
        'there occurs any Change of Control.',
      ]],
      ['Remedies upon Event of Default', 'If any Event of Default occurs and is continuing, the Administrative Agent shall, at the request of, or may, with the consent of, the Required Lenders, declare the commitment of each Lender to make Loans and any obligation of the L/C Issuer to make L/C Credit Extensions to be terminated; declare the unpaid principal amount of all outstanding Loans, all interest accrued and unpaid thereon, and all other amounts owing hereunder to be immediately due and payable, without presentment, demand, protest, or other notice of any kind; require that the Borrower Cash Collateralize the L/C Obligations; and exercise all rights and remedies available to it and the Lenders under the Loan Documents or applicable law. Upon an Event of Default under Section 8.01(f), these consequences occur automatically.'],
      ['Application of Funds', 'After the exercise of remedies, any amounts received on account of the Obligations shall be applied: first, to fees, indemnities, expenses, and other amounts payable to the Administrative Agent; second, to fees and other amounts payable to the Lenders and the L/C Issuer; third, to accrued and unpaid interest and fees ratably; fourth, to principal of the Loans, L/C Borrowings, and obligations under Secured Hedge Agreements and Secured Cash Management Agreements, and to Cash Collateralize undrawn Letters of Credit, ratably; and last, the balance, if any, to the Borrower or as otherwise required by law.'],
    ]],
    ['Administrative Agent', [
      ['Appointment and Authority', `Each of the Lenders and the L/C Issuer irrevocably appoints ${AGENT} to act on its behalf as the Administrative Agent hereunder and under the other Loan Documents and authorizes the Administrative Agent to take such actions on its behalf and to exercise such powers as are delegated to the Administrative Agent by the terms hereof, together with such actions and powers as are reasonably incidental thereto. The provisions of this Article are solely for the benefit of the Administrative Agent, the Lenders, and the L/C Issuer, and neither the Borrower nor any other Loan Party has rights as a third-party beneficiary of any of them.`],
      ['Rights as a Lender', 'The Person serving as the Administrative Agent shall have the same rights and powers in its capacity as a Lender as any other Lender and may exercise them as though it were not the Administrative Agent, and it and its Affiliates may accept deposits from, lend money to, act as financial adviser to, and generally engage in any kind of business with the Borrower or any Subsidiary as if it were not the Administrative Agent.'],
      ['Exculpatory Provisions', 'The Administrative Agent shall not have any duties or obligations except those expressly set forth herein and in the other Loan Documents, and its duties hereunder shall be administrative in nature. The Administrative Agent shall not be liable for any action taken or not taken by it with the consent of the Required Lenders or in the absence of its own gross negligence or willful misconduct as determined by a court of competent jurisdiction by final and nonappealable judgment.'],
      ['Resignation of Administrative Agent', 'The Administrative Agent may at any time give notice of its resignation to the Lenders, the L/C Issuer, and the Borrower. Upon receipt of any such notice, the Required Lenders shall have the right, with the consent of the Borrower while no Event of Default exists, to appoint a successor, which shall be a bank with an office in the United States having combined capital and surplus of at least $1,000,000,000. If no successor has accepted appointment within 30 days, the resignation nonetheless becomes effective.'],
      ['Collateral and Guaranty Matters', 'The Lenders irrevocably authorize the Administrative Agent to release any Lien on property granted to or held by it under any Loan Document upon termination of the Aggregate Commitments and payment in full of all Obligations, or that is sold or otherwise Disposed of as part of a transaction permitted hereunder, and to release any Guarantor from its obligations under the Guaranty if it ceases to be a Subsidiary as a result of a transaction permitted hereunder.'],
    ]],
    ['Miscellaneous', [
      ['Amendments, Etc.', 'No amendment or waiver of any provision of this Agreement or any other Loan Document shall be effective unless in writing signed by the Required Lenders and the Borrower and acknowledged by the Administrative Agent; provided that no such amendment shall, without the written consent of each Lender directly affected thereby, extend or increase its Commitment, postpone any date fixed for payment of principal or interest, reduce the principal of or rate of interest on any Loan, or change the pro rata sharing of payments, and no amendment shall release all or substantially all of the Collateral or the value of the Guaranty without the written consent of each Lender.'],
      ['Notices; Effectiveness; Electronic Communications', 'Notices and other communications provided for herein shall be in writing and delivered by hand or overnight courier, mailed by certified or registered mail, or sent by email, to the applicable address set forth on Schedule 10.02. Notices delivered through electronic communications to the extent provided in subsection (b) below are effective as provided in that subsection; the Platform is provided "as is" and "as available."'],
      ['Expenses; Indemnity; Damage Waiver', 'The Borrower shall pay all reasonable out-of-pocket expenses incurred by the Administrative Agent and its Affiliates, including the reasonable fees of one primary counsel, in connection with the syndication of the credit facilities, the preparation and administration of the Loan Documents, and any amendments, and all out-of-pocket expenses incurred by any Lender in the enforcement of its rights. The Borrower shall indemnify each Indemnitee against all losses, claims, damages, and liabilities arising out of the Loan Documents, except to the extent they result from the gross negligence, bad faith, or willful misconduct of that Indemnitee.'],
      ['Successors and Assigns', 'The provisions of this Agreement shall be binding upon and inure to the benefit of the parties hereto and their respective successors and assigns permitted hereby, except that the Borrower may not assign any of its rights hereunder without the prior written consent of each Lender. Any Lender may assign to one or more Eligible Assignees all or a portion of its rights and obligations under this Agreement, in a minimum amount of $5,000,000 for the Revolving Credit Facility and $1,000,000 for the Term A Facility, with the consent of the Borrower (not to be unreasonably withheld and deemed given if the Borrower does not object within ten Business Days) and of the Administrative Agent.'],
      ['Treatment of Certain Information; Confidentiality', 'Each of the Administrative Agent, the Lenders, and the L/C Issuer agrees to maintain the confidentiality of the Information, except that Information may be disclosed to its Affiliates and their respective partners, directors, officers, employees, agents, and advisers on a need-to-know basis; to the extent required by any regulatory authority or by law; to any actual or prospective assignee or participant that agrees to be bound by provisions substantially the same as these; and with the consent of the Borrower.'],
      ['Governing Law; Jurisdiction; Waiver of Jury Trial', 'This Agreement and the other Loan Documents shall be governed by the law of the State of New York. Each party irrevocably submits to the exclusive jurisdiction of the courts of the State of New York sitting in New York County and of the United States District Court for the Southern District of New York. EACH PARTY HERETO IRREVOCABLY WAIVES, TO THE FULLEST EXTENT PERMITTED BY APPLICABLE LAW, ANY RIGHT IT MAY HAVE TO A TRIAL BY JURY IN ANY LEGAL PROCEEDING DIRECTLY OR INDIRECTLY ARISING OUT OF OR RELATING TO THIS AGREEMENT OR ANY OTHER LOAN DOCUMENT.'],
      ['Counterparts; Integration; Effectiveness', 'This Agreement may be executed in counterparts, each of which shall constitute an original, but all of which when taken together shall constitute a single contract. This Agreement and the other Loan Documents constitute the entire contract among the parties relating to its subject matter and supersede any prior agreements, including the commitment letter among the Borrower and the Joint Lead Arrangers. This Agreement becomes effective when it has been executed by the Administrative Agent and the Administrative Agent has received counterparts bearing the signatures of each of the other parties hereto.'],
      ['Right of Setoff', 'If an Event of Default shall have occurred and be continuing, each Lender, the L/C Issuer, and each of their respective Affiliates is authorized at any time, to the fullest extent permitted by applicable law, to set off and apply any deposits (general or special, time or demand, provisional or final, in whatever currency) at any time held by it and any other obligations at any time owing by it to or for the credit of the Borrower against any of the Obligations then due, irrespective of whether demand has been made, provided that any Defaulting Lender shall promptly pay over to the Administrative Agent any amounts so set off.'],
      ['Interest Rate Limitation', 'Notwithstanding anything to the contrary in any Loan Document, the interest paid or agreed to be paid under the Loan Documents shall not exceed the maximum rate of non-usurious interest permitted by applicable law. If the Administrative Agent or any Lender receives interest in excess of that rate, the excess shall be applied to the principal of the Loans or, if it exceeds the unpaid principal, refunded to the Borrower.'],
      ['Survival of Representations and Warranties', 'All representations and warranties made hereunder and in any other Loan Document shall survive the execution and delivery hereof and thereof, and shall continue in full force and effect as long as any Loan or other Obligation remains unpaid or unsatisfied or any Letter of Credit remains outstanding, regardless of any investigation made by the Administrative Agent or any Lender.'],
      ['Severability', 'If any provision of this Agreement or the other Loan Documents is held to be illegal, invalid, or unenforceable, the legality, validity, and enforceability of the remaining provisions shall not be affected or impaired thereby, and the parties shall endeavor in good-faith negotiations to replace the illegal, invalid, or unenforceable provisions with valid provisions the economic effect of which comes as close as possible to that of the provisions so replaced.'],
      ['No Advisory or Fiduciary Responsibility', 'In connection with all aspects of each transaction contemplated hereby, the Borrower acknowledges and agrees that the credit facilities provided for hereunder and any related arranging or other services are an arm\'s-length commercial transaction between the Borrower and its Affiliates, on the one hand, and the Administrative Agent, the Joint Lead Arrangers, and the Lenders, on the other hand, and that none of them has assumed an advisory or fiduciary responsibility in favor of the Borrower.'],
      ['Acknowledgement Regarding Bail-In', 'Notwithstanding anything to the contrary in any Loan Document, each party acknowledges that any liability of any Affected Financial Institution arising under any Loan Document may be subject to the Write-Down and Conversion Powers of the applicable resolution authority, and agrees to be bound by the application of any such powers and by any Bail-In Action.'],
      ['USA PATRIOT Act Notice', 'Each Lender that is subject to the USA PATRIOT Act and the Administrative Agent hereby notifies the Borrower that it is required to obtain, verify, and record information that identifies each Loan Party, including the name and address of each Loan Party, which will allow it to identify each Loan Party in accordance with the Act and the Beneficial Ownership Regulation.'],
      ['Termination of Existing Credit Agreement', `Effective on the Closing Date, all commitments under the Existing Credit Agreement are terminated, all amounts owing thereunder are paid in full from the proceeds of the initial Credit Extensions, and ${EXISTING_AGENT}, as administrative agent thereunder, has delivered a payoff letter and authorized the release of all Liens securing those obligations.`],
    ]],
  ];
}
